var InputBoxHelper=(function(){
	function InputBoxHelper(view,inputBox,config){
		/**关联视图 */
		this._view=null;
		/**关联输入框 */
		this._inputBox=null;
		/**所有关联的输入框图片中的错误状态底图名字 */
		this._errBgName=null;
		/**配置 */
		this._config=null;
		/**全部输入框的下标列表 */
		this._allIdx=null;
		this._view=view;
		this._inputBox=inputBox;
		config=config || {errBgName:'bg_error' };
		this._config=config;
		this._errBgName=config.errBgName || 'bg_error';
		this.init();
	}

	__class(InputBoxHelper,'com.biz.common.helper.InputBoxHelper');
	var __proto=InputBoxHelper.prototype;
	/**
	*初始化
	*/
	__proto.init=function(){
		this._allIdx=[];
		for (var i=0;i < this._inputBox.numChildren;i++){
			this._allIdx.push(i);
			var inputImg=this.getInputImgByIdx(i);
			var errImg=inputImg.getChildByName(this._errBgName);
			if (!errImg){
				console.warn('没找到输入框的错误状态底图',this._errBgName);
				}else {
				errImg.visible=false;
			}
			inputImg.on("click",this,this.setInputState,[inputImg,1]);
		}
	}

	/**
	*设置输入框状态
	*@param inputImg 输入图
	*@param state 状态 0：普通 1：选中 2：错误
	*@returns
	*/
	__proto.setInputState=function(inputImg,state){
		(state===void 0)&& (state=0);
		if (!inputImg || inputImg.destroyed)return;
		var imgNames=['bg',this._errBgName]
		imgNames.forEach(function(n){
			var img=inputImg.getChildByName(n);
			img && (img.visible=false);
		})
		var showImgName=imgNames[state-1];
		var showImg=inputImg.getChildByName(showImgName);
		showImg && (showImg.visible=true)
		if (!state){
			inputImg.isSelected=false
		}
	}

	/**
	*设置全部输入框状态
	*@param state 状态 0：普通 1：选中 2：错误
	*@returns
	*/
	__proto.setAllInputState=function(state){
		(state===void 0)&& (state=0);
		var _this=this
		this._inputBox._childs.forEach(function(c){
			if (c instanceof KlInputImage){
				_this.setInputState(c,state);
			}
		})
	}

	/**
	*设置指定下标的输入框状态
	*@param idx 下标/下标列表
	*@param state 状态 0：普通 1：选中 2：错误
	*@returns
	*/
	__proto.setInputStateByIndex=function(idx,state){
		(state===void 0)&& (state=0);
		if ((idx instanceof Array)){
			for (var i=0;i < idx.length;i++){
				var _idx=parseInt(idx[i]);
				this.setInputStateByIndex(_idx,state);
			}
			}else if ((typeof idx=='number')&& !isNaN(idx)){
			this.setInputState(this.getInputImgByIdx(idx),state);
		}
	}

	__proto.getInputImgByIdx=function(idx){
		if (this._inputBox)return this._inputBox.getChildAt(idx);
		return null;
	}

	/**播放指定反馈 */
	__proto.playFeedback=function(type,config){
		config=config || this._config;
		return com.biz.common.helper.InputBoxHelper.playFeedback(this._view,type,config);
	}

	/**
	*全部空是否都填了
	*/
	__proto.isAllInput=function(){
		var allInputs=this._inputBox.getAllInputs();
		var blankIdx=allInputs.findIndex(function(v){
			return v.trim()=="";
		});
		if (~blankIdx){
			return false;
		}
		return true;
	}

	/**
	*错误的输入框下标列表
	*@param customCheck 自定义校验配置
	*@return 错误的输入框下标列表
	*/
	__proto.wrongIdx=function(customCheck){
		var len=this._inputBox.numChildren;
		var widx;
		var self=this;
		var checkFunc,multiAns,aconfig;
		if (customCheck){
			if ((typeof customCheck=='function')){
				checkFunc=customCheck;
				}else if ((customCheck instanceof Array)){
				multiAns=customCheck;
				}else if ((typeof customCheck=='object')){
				aconfig=customCheck;
			}
		}
		if (checkFunc){
			for(var idx=0;idx < len;idx++){
				var kipi=this._inputBox.getChildAt(idx);
				if (!checkFunc(idx,kipi.inputValue)){
					widx=widx || [];
					widx.push((idx));
				}
			}
			}else if (multiAns && multiAns.length){
			var isRight=false;
			var allWIdx=[];
			multiAns.forEach(function(ans,idx){
				if (!isRight){
					var widx=[];
					allWIdx.push(widx);
					if ((ans instanceof Array)){
						ans.forEach(function(val,_idx){
							var inputVal=self.getInputImgByIdx(_idx).inputValue;
							if (inputVal !=val){
								widx.push(_idx);
							}
						});
						}else if ((typeof ans=='string')){
						self._inputBox.answer=ans;
						var iwidx=self._inputBox.getWrongIdx();
						if (iwidx && iwidx.length){
							iwidx.forEach(function(__idx){
								widx.push(__idx);
							})
						}
					}
					if (!widx.length)isRight=true;
				}
			});
			if (!isRight){
				allWIdx.sort(function(a,b){
					return a.length-b.length;
				});
				widx=allWIdx[0];
			}
			}else if (aconfig){
			var answer=aconfig.answer || this._inputBox.answer;
			if (aconfig.anyOrder){
				if ((typeof answer=='string')){
					answer=answer.split(',');
				};
				var inputs=this._inputBox.getAllInputs();
				widx=ObjUtil.isArrayValuesMatch(inputs,answer);
				}else {
				this._inputBox.answer=answer;
				widx=this._inputBox.getWrongIdx();
			}
			}else {
			widx=this._inputBox.getWrongIdx();
		}
		widx=widx || [];
		return widx;
	}

	// public function verifyAnswer(config:Object=null,checkFunc:Function=null,multiAns:Array=null):Array {
	__proto.verifyAnswer=function(config,customCheck){
		var widx=this.wrongIdx(customCheck);
		var isRight=widx.length===0;
		var holdInputState=this._config.holdInputState;
		if (isRight){
			!holdInputState && this.setInputStateByIndex(this._allIdx);
			this.playFeedback("right",config);
			return [];
			}else {
			!holdInputState && this.setInputStateByIndex(widx,2);
			this.playFeedback("wrong",config);
			return widx;
		}
	}

	InputBoxHelper.playFeedback=function(view,type,config){
		if (type!=="right" && type!=="wrong")return false;
		var fb;
		if (type==="right"){
			fb=config && (config.right ? config.right :config);
			}else {
			fb=config && (config.wrong ? config.wrong :config);
		}
		if (fb){
			var ani=fb.ani===true ? (type==="right" ? 1 :2):fb.ani;
			ani && view.showAnswerFace(ani);
			var sound=fb.sound===true ? (type==="right" ? "share/sound/rush_flag.wav" :"share/sound/anwser_wrong.wav"):fb.sound;
			sound && view.playSound(sound);
			fb.lockView && (view.mouseEnabled=false);
			return true
		}
		return false
	}

	return InputBoxHelper;
})()


