//class com.klzz.res.PageResStatus
var PageResStatus=(function(){
	function PageResStatus(vconfig,idx){
		/**对应的加载事务 */
		this._trans=null;
		/**是否加载完成 */
		this._loaded=false;
		/**是否正在使用 */
		this._inUse=false;
		/**对应的页面配置 */
		this._vconfig=null;
		/**下标 */
		this._idx=0;
		this._vconfig=vconfig;
		this._idx=idx;
	}

	__class(PageResStatus,'com.klzz.res.PageResStatus');
	var __proto=PageResStatus.prototype;
	/**销毁资源 */
	__proto.destroyRes=function(force){
		(force===void 0)&& (force=false);
		this.loaded=false;
	}

	/**原依赖资源 */
	__getset(0,__proto,'oriRes',function(){
		return this._vconfig.res;
	});

	/**标识 */
	__getset(0,__proto,'flag',function(){
		return "pageRes"+this._idx;
	});

	/**是否加载完成 */
	// }
	__getset(0,__proto,'loaded',function(){
		return this._loaded;
		},function(v){
		if (v==this._loaded)
			return;
		this._loaded=v;
		if (v){
			if (this.res && this.res.length){
				var ts=Browser.now();
				var i;
				for(var $each_i in this.res){
					i=this.res[$each_i];
					if (ResManager.isManageRes(i))
						ResManager.dicLoadedRes.set(i.url,{inUse:false,freeTime:ts});
				}
			}
			this._trans=null;
		}else {}
	});

	/**下标 */
	__getset(0,__proto,'idx',function(){
		return this._idx;
	});

	/**依赖的资源列表 */
	__getset(0,__proto,'res',function(){
		return this.oriRes;
	});

	__getset(0,__proto,'trans',function(){
		return this._trans;
		},function(trs){
		this._loaded=false;
		this._trans=trs;
	});

	/**关卡资源是否在用 */
	__getset(0,__proto,'inUse',function(){
		return this._inUse;
		},function(v){
		if (this._inUse==v)
			return;
		this._inUse=v;
		if (!this.res || !this.res.length)
			return;
		var ts=Browser.now();
		var i;
		for(var $each_i in this.res){
			i=this.res[$each_i];
			if (!ResManager.isManageRes(i))
				continue ;
			var robj=ResManager.dicLoadedRes.get(i.url);
			if (!robj){
				console.warn("ResManager","这资源怎么会没加载呢？",i.url);
				}else {
				robj.inUse=v;
				if (!v)
					robj.freeTime=ts;
				ResManager.dicLoadedRes.set(i.url,robj);
			}
		}
	});

	return PageResStatus;
})()


/**新资源管理，主要解决：
*1、页面预加载资源过多
*2、页面资源缓存、销毁机制不合理
*/
//class com.biz.common.res.NewResMgr
var NewResMgr=(function(){
	function NewResMgr(){}
	__class(NewResMgr,'com.biz.common.res.NewResMgr');
	/**是否启用 */
	__getset(1,NewResMgr,'enable',function(){
		return !(!NewResMgr.config);
	});

	NewResMgr.__init__=function(cfg){
		if (!cfg || !cfg.enabled)return;
		NewResMgr.config=cfg;
		if ((typeof NewResMgr.config=='object')){
			NewResMgr.config.maxAtlasLoadCount && (NewResMgr.ATLAS_MAX_LOAD_COUNT=NewResMgr.config.maxAtlasLoadCount);
			NewResMgr.config.maxImgLoadCount && (NewResMgr.IMAGES_MAX_LOAD_COUNT=NewResMgr.config.maxImgLoadCount);
			NewResMgr.config.maxAniLoadCount && (NewResMgr.SKELETON_MAX_LOAD_COUNT=NewResMgr.config.maxAniLoadCount);
			NewResMgr.config.maxCacheCount && (NewResMgr.MAX_CACHE_RES_NUM=NewResMgr.config.maxCacheCount);
			if (NewResMgr.config.ignoreShareRes && NewResMgr.config.ignoreShareRes.lengths){
				NewResMgr.IGNORE_SHARE_RES=NewResMgr.IGNORE_SHARE_RES.concat(NewResMgr.config.ignoreShareRes);
			}
		}
		ResManager.pageResStatusCls=NewPageResStatus;
		ResManager.customLoadPageAtFunc=com.biz.common.res.NewResMgr.loadPageAt;
		ResManager.customCheckForFreeFunc=com.biz.common.res.NewResMgr.checkForFreeRes;
		ResManager.customClearAllResFunc=com.biz.common.res.NewResMgr.clearAllRes;
		com.biz.common.res.NewResMgr.loadResFilters.push(ResFilter.handleSound);
		com.biz.common.res.NewResMgr.loadResFilters.push(ResFilter.iosExcludeTTF);
	}

	NewResMgr.clearAllRes=function(force){}
	NewResMgr.loadPageAt=function(idx,onComplete){
		com.biz.common.res.NewResMgr.stopCurrLoadPage();
		console.debug("NewResMgr.loadPageAt","开始加载第 "+idx+" 页的资源 ");
		var prs=ResManager.pageResStatusList[idx];
		onComplete=Handler.create(null,com.biz.common.res.NewResMgr.onPageResLoaded,[prs,onComplete]);
		var onProgress=Handler.create(null,com.biz.common.res.NewResMgr.onPageLoadProgress,[idx],false);
		prs.startLoadRes(onComplete,onProgress,com.biz.common.res.NewResMgr.loadResFilters);
		com.biz.common.res.NewResMgr.currLoadPageIdx=idx;
		ViewManager.instance.once("mainViewPrepared",null ,com.biz.common.res.NewResMgr.onPagePrepared,[idx]);
	}

	NewResMgr.stopCurrLoadPage=function(){
		var clpi=com.biz.common.res.NewResMgr.currLoadPageIdx;
		if (clpi < 0)
			return;
		console.debug("NewResMgr.stopCurrLoadPage","终止之前的加载任务，页下标：",com.biz.common.res.NewResMgr.currLoadPageIdx);
		ResManager.pageResStatusList[clpi].stopLoadRes();
		com.biz.common.res.NewResMgr.currLoadPageIdx=-1;
		ViewManager.instance.off("mainViewPrepared",null,com.biz.common.res.NewResMgr.onPagePrepared,true);
	}

	NewResMgr.onPageResLoaded=function(prs,onComplete,cancel){
		com.biz.common.res.NewResMgr.currLoadPageIdx=-1;
		var apf=com.biz.common.res.NewResMgr.actPageFlow;
		var cpidx=apf.indexOf(prs.idx);
		if (~cpidx)apf.splice(cpidx,1);
		if (cancel){
			prs.abortLoad();
			apf.unshift(prs.idx);
			console.debug("NewResMgr.onPageResLoaded 将中止加载的页放至页序列表首位，结果：",apf);
			}else {
			prs.loaded=true;
			apf.push(prs.idx);
			console.debug("NewResMgr.onPageResLoaded 将完成加载的页放至页序列表末位，结果：",apf);
			var gl=VipThink.gameLoader;
			if (gl){
				gl.instance.handleLoadedResList((prs).finalRes);
			}
		}
		onComplete && onComplete.runWith([prs.idx,cancel]);
	}

	NewResMgr.onPageLoadProgress=function(idx,progress){
		console.log("NewResMgr.onPageLoadProgress： 第",idx,"页的资源加载进度：",progress);
		KlEventCenter.event("pageLoadProgress",{index:idx,progress:progress });
	}

	NewResMgr.onPagePrepared=function(idx,mv){
		if (mv.currIndices[0]!==idx){
			console.warn("NewResMgr.onPagePrepared","当前页下标怎么会跟已加载页下标不一样？ idx: ",idx,"mv.idx:",mv.currIndices[0]);
			return;
		};
		var prs=ResManager.pageResStatusList[ResManager.currPageIdx];
		prs && (prs.inUse=false);
		prs=ResManager.pageResStatusList[idx];
		prs && (prs.inUse=true);
		ResManager.setCurrPageIdxOnly(idx);
		com.biz.common.res.NewResMgr.autoClearRes();
	}

	NewResMgr.checkForFreeRes=function(){}
	NewResMgr.autoClearRes=function(){
		var oriMem=NaN;
		while (ResManager.dicLoadedRes.keys.length > com.biz.common.res.NewResMgr.MAX_CACHE_RES_NUM){
			oriMem=oriMem || ResManager.currMem;
			var rmidx=com.biz.common.res.NewResMgr.actPageFlow.shift();
			var prs=ResManager.pageResStatusList[rmidx];
			prs && prs.destroyRes();
		}
		if (oriMem){
			console.debug("NewResMgr.autoClearRes","共清理资源缓存：",oriMem-ResManager.currMem,"M，当前页序：",com.biz.common.res.NewResMgr.actPageFlow);
		}
	}

	NewResMgr.minimizeRes=function(res,filters){
		if (!res || !res.length)
			return null;
		var anis=ResManager.getAllAnis(res);
		var excludeList=[];
		var addedImgs=[];
		var addedSkeletons=[];
		var addedSkeletonNames=[];
		var addedAtlas=[];
		var finalRes=[];
		for (var idx=0 in res){
			idx=parseInt(idx);
			var v=res[idx];
			var url=v.url;
			if (!ResManager.keepRes(v,filters))url=null;
			if (url){
				var fileExt=Utils.getFileExtension(url);
				var rtype=v.type || StringUtil.getTypeFromUrl(url);
				var fileName=StringUtil.getFileName(url,true);
				switch (rtype){
					case "image":
						if (ResManager.isSkRes(url,anis)){
							addedSkeletons.push(v);
							}else if (addedImgs.length < com.biz.common.res.NewResMgr.IMAGES_MAX_LOAD_COUNT){
							addedImgs.push(v);
							}else {
							excludeList.push(v);
						}
						break ;
					case "atlas":
						if (addedAtlas.length < com.biz.common.res.NewResMgr.ATLAS_MAX_LOAD_COUNT){
							addedAtlas.push(v);
						}
						break ;
					case "arraybuffer":
						if (fileExt=="sk" && addedSkeletonNames.length < com.biz.common.res.NewResMgr.SKELETON_MAX_LOAD_COUNT){
							addedSkeletons.push(v);
							addedSkeletonNames.push(fileName);
						}
						break ;
					case "sound":
						break ;
					default :
						finalRes.push(v);
						break ;
					}
			}
		}
		return finalRes.concat(addedImgs,addedAtlas,addedSkeletons);
	}

	NewResMgr.config=null;
	NewResMgr.ATLAS_MAX_LOAD_COUNT=99;
	NewResMgr.IMAGES_MAX_LOAD_COUNT=3;
	NewResMgr.SKELETON_MAX_LOAD_COUNT=99;
	NewResMgr.MAX_CACHE_RES_NUM=40;
	NewResMgr.actPageFlow=[];
	NewResMgr.loadResFilters=[];
	NewResMgr.currLoadPageIdx=-1;
	__static(NewResMgr,
	['IGNORE_SHARE_RES',function(){return this.IGNORE_SHARE_RES=["res/atlas/share/ui.atlas"];}
	]);
	return NewResMgr;
})()


/**
*资源过滤器
*/
//class com.biz.common.res.ResFilter
var ResFilter=(function(){
	function ResFilter(){}
	__class(ResFilter,'com.biz.common.res.ResFilter');
	ResFilter.getUrlInfo=function(v){
		if (!v)return null;
		ObjUtil.clearObj(ResFilter._URL_INFO);
		var r=ResFilter._URL_INFO;
		if ((typeof v=='string'))r.url=v;
		if ((typeof v=='object')){
			r.url=v.url;
			r.type=v.type;
		}
		if (r.url && !r.type)r.type=StringUtil.getTypeFromUrl(r.url);
		return r;
	}

	ResFilter.handleSound=function(v,idx){
		var uinfo=ResFilter.getUrlInfo(v);
		if (!uinfo || !uinfo.url)return false;
		if (uinfo.type=="sound"){
			return false;
		}
		return true;
	}

	ResFilter.excludeNonBgImgs=function(v,idx){
		var uinfo=ResFilter.getUrlInfo(v);
		if (!uinfo || !uinfo.url)return false;
		var fileName=StringUtil.getFileName(uinfo.url);
		if (uinfo.type==="image" && fileName.includes("bg")){
			return true;
		}
		return false;
	}

	ResFilter.iosExcludeTTF=function(v,idx){
		if(Browser.onIOS){
			var uinfo=ResFilter.getUrlInfo(v);
			if (!uinfo || !uinfo.url)return false;
			if (uinfo.type!=="ttf")return true;
			var _versisonStr=VipThink.config.version;
			if(ResFilter.checkPlugin(_versisonStr,"2.0.13")){
				return false;
			}
		}
		return true;
	}

	ResFilter.checkPlugin=function(a,b){
		a=ResFilter.toNum(a);
		b=ResFilter.toNum(b);
		if(a>b){
			return false;
			}else{
			return true;
		}
	}

	ResFilter.toNum=function(a){
		var a=a.toString();
		var c=a.split('.');
		var num_place=["","0","00","000","0000"];
		var r=num_place.reverse();
		for (var i=0;i<c.length;i++){
			var len=c[i].length;
			c[i]=r[len]+c[i];
		};
		var res=c.join('');
		return res;
	}

	ResFilter._URL_INFO={};
	return ResFilter;
})()


