		this._CHECK_TOUCH_TIME=20;
		/**报告状态 */
		this._reportStatus={
			hasReport:false
		};
		/**当前课件视图 */
		this._currGameView=null;
		/**当前正交互的层（当与课件视图交互时停止更新） */
		this._currTouchLayer=null;
