//class com.biz.filters.SendMsgFilter
var SendMsgFilter=(function(){
	function SendMsgFilter(){
		this.req=null;
		this.resp=null;
		this._chain=null;
	}

	__class(SendMsgFilter,'com.biz.filters.SendMsgFilter');
	var __proto=SendMsgFilter.prototype;
	Laya.imps(__proto,{"com.klzz.pattern.IFilter":true})
	//implements start
	__proto.doFilter=function(req,resp,chain){
		this.req=req;
		this.resp=resp;
		this._chain=chain;
		if ((req instanceof com.biz.model.ReqVO )){
			this.updateReqHandler();
			VipThink.socketHdr.sendMsg(
			req.ptl,
			req.data,
			req.handler,
			req.hdrKey);
			}else {
			if (req.broadcast){
				VipThink.socketHdr.broadcast(
				req.action,
				req.data,
				req.inRoom ? 2 :1,
				req.userType,
				req.whiteList,
				req.blackList);
				if (req.action !="EnterRoom" && !req.inRoom){
					console.warn("SendMsgFilter - excute - 非EnterRoom全局广播,type:1, action:"+req.action+", data:"+JSON.stringify(req.data));
				}
				}else {
				this.updateReqHandler();
				VipThink.socketHdr.sendMsg(
				req.ptl,
				req.data || {},
				req.handler,
				req.hdrKey);
			}
		}
		if(VipThink.cfgCourse && VipThink.cfgCourse.isAIrecord){
			VipThink.viewMgr.event("aiRecordAddData",req);
		}
		if (req.handler)
			return false;
		else
		return chain.doFilter(req,resp);
	}

	/**回调处理 */
	__proto.onResult=function(data){
		this.resp=data;
		this._chain.doFilter(this.req,this.resp);
	}

	/**
	*更新req对象中的回调
	*/
	__proto.updateReqHandler=function(){
		this.req.handler=(this.req && this.req.handler!==null)? OwnHandler.kreate("trans",this,this.onResult):null;
	}

	/**当前用户 */
	__getset(0,__proto,'user',function(){
		return VipThink.user;
	});

	SendMsgFilter.BLANK_ARRAY=[];
	return SendMsgFilter;
})()


