//class com.biz.filters.HandleRenderFilter
var HandleRenderFilter=(function(){
	function HandleRenderFilter(){
		/**是否执行下一个 */
		this._nextFilter=true;
	}

	__class(HandleRenderFilter,'com.biz.filters.HandleRenderFilter');
	var __proto=HandleRenderFilter.prototype;
	Laya.imps(__proto,{"com.klzz.pattern.IFilter":true})
	//implements start
	__proto.doFilter=function(req,resp,chain){
		if (!req.xpath){
			console.warn("HandleRenderFilter#page","Req object's xpath is missing.");
			}else {
			var cmd=Pool.getItemByClass(ObjUtil.getClsName(RenderByUserCommand,true),RenderByUserCommand);
			var target;
			var idxShu=req.xpath.indexOf("|");
			if (idxShu >=0)
				req.xpath=req.xpath.substr(idxShu+1);
			this._nextFilter=true;
			if (req.xpath.indexOf("root")==req.xpath.length-4){
				target=HandleRenderFilter.viewMgr.mainView;
				}else {
				var currView=HandleRenderFilter.viewMgr.currSubview;
				if (currView && (currView.status=="prepared" || currView.status=="ctored")){
					var xpathInfo=req.xpath.split(".");
					var rootIdx=xpathInfo.indexOf("root");
					var viewName=xpathInfo[rootIdx+2];
					if (viewName!==currView.name){
						console.warn("HandleRenderFilter.doFilter#page 警告：要还原的小题与当前小题不一致！要还原的：",viewName,"当前的：",currView.name);
						}else {
						target=HandleRenderFilter.viewMgr.getCompByXpath(req.xpath,req.pageIdx,req.viewIdx);
					}
					}else {
					HandleRenderFilter.viewMgr.mainView.on("changed",this,this.onPageStatusChanged,[
					Handler.create(this,this.doFilter,[req,resp,chain]),]);
					this._nextFilter=false;
				}
			}
			if (target){
				var cmdData=ObjectTools.copyObjFast(req);
				delete cmdData.xpath;
				cmd.setDetail(
				target,
				cmdData);
			}
			if (cmd.isValid){
				cmd.execute();
				}else {
				cmd.recover();
			}
		}
		if (this._nextFilter)
			return chain.doFilter(req,resp);
		else
		return false;
	}

	/**
	*当页面状态改变
	*@param hdr 继续执行的回调
	*@param data 状态改变数据
	*/
	__proto.onPageStatusChanged=function(hdr,data){
		if (data.status=="ctored"){
			hdr.run();
			HandleRenderFilter.viewMgr.mainView.off("changed",this,this.onPageStatusChanged);
		}
	}

	/**视图管理器 */
	__getset(1,HandleRenderFilter,'viewMgr',function(){
		return ViewManager.instance;
	});

	return HandleRenderFilter;
})()


