//class com.biz.model.room.control.SplitPackageCtr
var SplitPackageCtr=(function(){
	function SplitPackageCtr(ctr,count,time){
		this.ctr=null;
		this.packageArr=null;
		this.isTimer=false;
		this.count=0;
		// 每个包最大数量
		this.time=0;
		(count===void 0)&& (count=50);
		(time===void 0)&& (time=500);
		this.ctr=ctr;
		this.count=count;
		this.time=time;
		this.isTimer=false;
		this.packageArr=[];
	}

	__class(SplitPackageCtr,'com.biz.model.room.control.SplitPackageCtr');
	var __proto=SplitPackageCtr.prototype;
	__proto.add=function(id,data){
		this.packageArr.push({id:id,data:data});
		this.timer(true);
	}

	__proto.send=function(count){
		(count===void 0)&& (count=50);
		if (this.packageArr.length==0)
			return;
		var arr=[];
		var key;
		while (count !=0){
			var obj=this.packageArr.shift();
			if (obj){
				arr.push(obj);
			}
			else{
				break ;
			}
			count--;
		}
		this.ctr.addDatas("",arr);
		if (this.packageArr.length==0){
			this.timer(false);
		}
	}

	__proto.timer=function(val){
		if (this.isTimer==val)
			return;
		this.isTimer=val;
		if (val){
			Laya.timer.clearAll(this);
			Laya.timer.loop(this.time,this,function(){
				this.send(this.count);
			});
		}
		else{
			Laya.timer.clearAll(this);
			this.send(-1);
		}
	}

	return SplitPackageCtr;
})()


