	__proto.findData=function(obj){
		var id=obj["id"];
		var num=obj["num"] ||-1;
		var keys=obj["keys"];
		var arr=[];
		var idData;
		var nunData;
		if(id){
			if(num==-1){
				idData=this.getData(id);
				if(idData){
					for(var key in idData){
						nunData=idData[key];
						arr.push({
							id:id,
							num:key,
							data:this.filterKey(nunData,keys)
						});
					}
				}
			}
			else{
				nunData=this.getData(id,num);
				if(nunData){
					arr.push({
						id:id,
						num:num,
						data:this.filterKey(nunData,keys)
					});
				}
			}
		}
		else{
			for(var key in this.list){
				idData=this.list[key];
				for(var key1 in this.list){
					nunData=idData[key1];
					arr.push({
						id:key,
						num:key1,
						data:this.filterKey(nunData,keys)
					});
				}
			}
		}
		return arr;
	}

