		this.reportSLS("RoomManager.recover: "+this.isFirstRecover+","+VipThink.user.isTech);
		this.saveRoomData();
		CustomRoomDataUtil.readRoomData(uidStr,Handler.create(this,this.handleReadData));
		VipThink.nativeAPI.sendToNative("viewInitComplete");
