	/**
	*处理应用端通过mate接口发送过来的minorType为socket的事件
	*@param param:*[description]
	*@return [description]
	*/
	__proto.socket=function(param){
		var data=param.data;
		if (!data){
			console.debug('MateManager - socket - data is undefined');
			return;
		}
		if (data.act=="reBuild"){
			var same=true;
			var value=data.value;
			if (value.server==undefined)
				value.server=[];
			if (value){
				console.debug("MateManager - socket - value 收到应用端返回的新的socket地址:"+JSON.stringify(value));
				if (value.server && value.server.length){
					function compareArr (arr1,arr2){
						if (!arr1)
							return false;
						if (!arr2 || !arr2.length){
							return false;
						}
						if (arr1.length !=arr2.length){
							return false;
						}
						for (var i=0;i < arr1.length;i++){
							if (arr1.indexOf(arr2[i])==-1){
								return false;
							}
						}
						return true;
					}
					if (!compareArr(value.server,VipThink.launchParam.server)){
						same=false;
					}
					}else {
					delete value.server;
					for (var key in value){
						if (value[key]==undefined || VipThink.launchParam[key]==undefined){
							console.error('MateManager - socket - value error, key:'+key);
							break ;
						}
						if (value[key] !=VipThink.launchParam[key]){
							same=false;
							break ;
						}
					}
					value.server=[];
				}
				if (!same){
					console.debug("MateManager - socket - value，应用返回的新的socket地址与原来的地址不同，将重置socket，并重连");
					Klzz.socket.reset();
					VipThink.launchParam.update(value);
					Klzz.socket.switchTo(VipThink.launchParam.firstSocketInfo)
					Klzz.socket.connect();
					}else {
					console.debug("MateManager - socket - 应用返回的新的socket参数没变化，不自动重连")
				}
				}else {
				console.error('MateManager - socket - value is undefined');
			}
		}
	}

