	/**
	*适配andoird和ios旧版本数据格式
	*/
	__proto.adaptIosAndAndoird=function(data){
		if (!data)
			return data;
		if (Browser.onPC)
			return data;
		var version=VipThink.config.version && (VipThink.config.version.replace(/\./g,""));
		if (version){
			if (Browser.onIOS){
				version=version.split("-")[1];
				if (version){
					version=parseInt(version);
					if (version > 238)
						return data;
				}
			}
			if (Browser.onAndroid){
				version=parseInt(version);
				if (version > 221)
					return data;
			}
			}else {
			return data;
		}
		if ((data instanceof Array)|| (Object.prototype.toString.call(data)=="[object Array]")){
			var arr=[];
			for (var i=0;i < data.length;i++){
				var item=data[i];
				if (item && (item.key=="privateChat" || item.key=="onAir")){
					item.value=this.arrToObj(item.value);
					arr.push(item);
					}else {
					if (item && (item[1]=="privateChat" || item[1]=="onAir")){
						var value=item[2];
						if ((value instanceof Array)|| (Object.prototype.toString.call(value)=="[object Array]")){
							item[2]=this.arrToObj(value);
						}
						item=this.arrToObj(item);
						arr.push(item);
					}
					else {
						arr.push(item);
					}
				}
			}
			return arr;
			}else {
			return data;
		}
	}

	/**
	*数据转成object andoird 2.2.1 ios 2.3.8
	*/
	__proto.arrToObj=function(arr){
		if (!arr)
			return {};
		var obj={};
		for (var i=0;i < arr.length;i++){
			obj[i+""]=arr[i];
		}
		return obj;
	}

