	/**
	*初始化
	*/
	__proto._init_=function(args){
		console.log("AnimationCommand _init_");
		if (args && args[0]){
			this._xpath=args[0].xpath;
			this._nValue=args[0].n;
			if (this._nValue){
				if ((typeof this._nValue=='string')){
					this._nValue=JSON.parse(this._nValue);
				}
			}
		}
	}

