/**
*自定义数据,房间通讯类
*@author wuwenjie
*
*/
//class com.biz.utils.CustomRoomDataUtil
var CustomRoomDataUtil=(function(){
	var cbData;
	function CustomRoomDataUtil(){}
	__class(CustomRoomDataUtil,'com.biz.utils.CustomRoomDataUtil');
	CustomRoomDataUtil.hasProtocol=function(protocol){
		return com.biz.utils.CustomRoomDataUtil.protocolArr.indexOf(protocol)>=0;
	}

	CustomRoomDataUtil.sendToRoom=function(data,ids,callback){
		var sendData={ids:ids,content:data};
		VipThink.socketHdr.sendMsg("SendToRoom",sendData,callback,"SendToRoomResult");
	}

	CustomRoomDataUtil.sendMsg=function(protocolName,data,ids,callback){
		var sendData={
			ids:ids || [],
			content:{
				name:protocolName,
				data:data
		}};
		VipThink.socketHdr.sendMsg("SendToRoom",sendData,callback,"SendToRoomResult");
	}

	CustomRoomDataUtil.addMsgListener=function(msgName,caller,listener,isCustom){
		(isCustom===void 0)&& (isCustom=false);
		if(isCustom && !com.biz.utils.CustomRoomDataUtil.hasProtocol(msgName)){
			com.biz.utils.CustomRoomDataUtil.protocolArr.push(msgName);
		};
		var arr=CustomRoomDataUtil.callbackList[msgName];
		if (!arr){
			CustomRoomDataUtil.callbackList[msgName]=arr=[];
		}
		arr.push(new cbData(caller,listener));
	}

	CustomRoomDataUtil.removeMsgListener=function(msgName,caller,listener){
		var index=com.biz.utils.CustomRoomDataUtil.protocolArr.indexOf(msgName);
		if(index>=0){
			com.biz.utils.CustomRoomDataUtil.protocolArr.splice(index,1);
		};
		var arr=CustomRoomDataUtil.callbackList[msgName];
		if (arr){
			var len=arr.length;
			for (var i=len-1;i >-1;i--){
				var cb=arr[i];
				if (cb.caller==caller && cb.listener==listener){
					arr.splice(i,1);
					return;
				}
			}
		}
	}

	CustomRoomDataUtil.onReceiveInfo=function(cmd,data){
		var uid=0;
		var key="";
		var _data;
		if (data.content){
			var obj;
			try{
				obj=JSON.parse(data.content);
			}
			catch (e){
			}
			if (obj && obj.hasOwnProperty("name")){
				key=obj["name"];
				_data=obj["data"];
				uid=data["userId"];
			}
		}
		else if (data["protocol"]){
			try{
				data["data"]=data["data"] ? JSON.parse(data["data"]):null;
				_data=data;
				key=cmd;
			}
			catch (e){
			}
		};
		var arr=CustomRoomDataUtil.callbackList[key];
		if (arr){
			var length=arr.length;
			for (var j=0;j < length;j++){
				var cb=arr[j];
				cb.listener.apply(cb.caller,[_data,key,uid]);
			}
		}
	}

	CustomRoomDataUtil.setRoomData=function(key,data,callback){
		if (key==null || data==null){
			return;
		};
		if (typeof (data)=="object"){
			data=JSON.stringify(data);
		}
		else if (typeof (data)=="number"){
			data=data+"";
		};
		var sendData={key:key,data:data};
		VipThink.socketHdr.sendMsg("SetRoomData",sendData,callback,"SetRoomDataResult");
	}

	CustomRoomDataUtil.readRoomData=function(uid1,callback){
		var sendData={uid:uid1};
		VipThink.socketHdr.sendMsg("ReadRoomData",sendData,callback,"ReadRoomDataResult");
	}

	CustomRoomDataUtil.callbackList={};
	__static(CustomRoomDataUtil,
	['protocolArr',function(){return this.protocolArr=["SendToRoomResult"];}
	]);
	CustomRoomDataUtil.__init$=function(){
		//class cbData
		cbData=(function(){
			function cbData(call,fc){
				this.caller=null;
				this.listener=null;
				this.caller=call;
				this.listener=fc;
			}
			__class(cbData,'');
			return cbData;
		})()
	}

	return CustomRoomDataUtil;
})()


/***
*定位功能类
**/
//class com.biz.utils.LocationUtil
var LocationUtil=(function(){
	function LocationUtil(){}
	__class(LocationUtil,'com.biz.utils.LocationUtil');
	LocationUtil.showLocation=function(id,args,complete,broadcast){
		(broadcast===void 0)&& (broadcast=true);
		var cfg=ServiceCenter.gameCfgService.getLocationDefine(id);
		console.debug("开始打开定位:",id,cfg && cfg.name);
		if (!cfg){
			console.warn("无效的locationId",id);
			return;
		}
		if (broadcast && cfg.broadcast && !LocationUtil.isShowOrLoading(id)){
			var transParam=LocationUtil.injectParam(args);
			TransManager.doTrans("locViewTrans",null,[{action:"doTrans",data:{locId:id,cmd:"showLocation",args:transParam,transType:"locViewTrans"}}])
		}
		if (LocationUtil.isLocationOpened(id)){
			if (cfg.group){
				}else {
				console.warn("定位已经打开，请确认是不是单例定位:",cfg.id,cfg.name);
				return;
			}
		}
		if (LocationUtil.isLocationLoading(id)){
			console.warn("定位正在加载中",id);
			return;
		}
		LocationUtil.tryShowLocList.push({cfg:cfg,args:args,complete:complete});
		LocationUtil.tryShowLocation();
	}

	LocationUtil.removeLocation=function(id,force,args,broadcast){
		(force===void 0)&& (force=true);
		(broadcast===void 0)&& (broadcast=true);
		var cfg=ServiceCenter.gameCfgService.getLocationDefine(id);
		if (!cfg){
			console.warn("removeLocation 无效的locationId",id);
			return;
		};
		var view=LocationUtil.loc2ViewMap[id];
		if (broadcast && cfg.broadcast && LocationUtil.isShowOrLoading(id)){
			var transParam=LocationUtil.injectParam(args);
			TransManager.doTrans("locViewTrans",null,[{action:"doTrans",data:{locId:id,cmd:"removeLocation",args:transParam,transType:"locViewTrans"}}])
		}
		if (view){
			var realClose=view.tryClose(args)|| force;
			realClose && ViewUtil.removeView(view,true);
			}else {
			var runTimeClass=LocationUtil.getRuntimeClass(id);
			if (runTimeClass){
				var tryCloseFun=runTimeClass["classTryClose"];
				if (tryCloseFun){
					tryCloseFun.apply(runTimeClass,[args]);
				}
			}
		}
	}

	LocationUtil.removeAllLocation=function(force){
		(force===void 0)&& (force=false);
		var allLocView=DictionaryUtil.toValueArray(LocationUtil.loc2ViewMap);
		var len=allLocView.length;
		for (var index=0;index < len;index++){
			var v=allLocView[index];
			if (!force){
				if ((v.locCfg).netCloseRemove){
					ViewUtil.removeView(v);
				}
				}else {
				ViewUtil.removeView(v);
			}
		}
	}

	LocationUtil.updateLocation=function(id,args){
		var view=LocationUtil.loc2ViewMap[id];
		if (view){
			view.updateParam(args);
		}
	}

	LocationUtil.sync=function(view,args){
		if (view.locCfg.broadcast){
			var transParam=LocationUtil.injectParam(args);
			TransManager.doTrans("locViewTrans",null,[{action:"doTrans",data:{locId:view.locCfg.id,cmd:"sync",args:transParam,transType:"locViewTrans"}}])
			}else {
			console.warn("配置广播数据!",view.locCfg.broadcast,"不需要广播",view.locCfg.id);
		}
	}

	LocationUtil.handlerSync=function(id,args){
		var view=LocationUtil.loc2ViewMap[id];
		if (view){
			view.handlerSync(args);
			}else {
			var runTimeClass=LocationUtil.getRuntimeClass(id);
			if (runTimeClass){
				var handlerSyncFun=runTimeClass["classHandlerSync"];
				if (handlerSyncFun){
					handlerSyncFun.apply(runTimeClass,[args]);
				}
			}
		}
	}

	LocationUtil.isShowOrLoading=function(loc){
		if (LocationUtil.isLocationOpened(loc)|| LocationUtil.isLocationOpened(loc)){
			return true;
		}
		return false;
	}

	LocationUtil.isLocationOpened=function(loc){
		return LocationUtil.loc2ViewMap [loc];
	}

	LocationUtil.isLocationLoading=function(loc){
		return LocationUtil.loadingMap[loc];
	}

	LocationUtil.getLocationView=function(loc){
		return LocationUtil.loc2ViewMap[loc];
	}

	LocationUtil.onRemoveView=function(view){
		var key=DictionaryUtil.getValueKey(LocationUtil.loc2ViewMap,view);
		console.log("关闭定位->,",key);
		DictionaryUtil.removeValue(LocationUtil.loc2ViewMap,view);
		var clearFun=view["clear"];
		if (clearFun){
			clearFun.apply(view);
		};
		var loc=parseInt(key);
		var cfg=ServiceCenter.gameCfgService.getLocationDefine(loc);
		LocationUtil.releaseViewRes(cfg);
	}

	LocationUtil.loadViewRes=function(def,compelte){
		if (def.resId){
			var resListDefine=ServiceCenter.gameCfgService.getResListDefine(def.resId);
			Laya.loader.load(resListDefine.res,Handler.create(LocationUtil,function(){
				compelte && compelte.runWith(true);
			}))
			}else {
			compelte && compelte.runWith(true);
		}
	}

	LocationUtil.releaseViewRes=function(def){}
	LocationUtil.tryShowLocation=function(){
		if (DictionaryUtil.getMemberCount(LocationUtil.loadingMap)> 0){
			console.log("当前有页面在加载重！",DictionaryUtil.toKeyArray(LocationUtil.loadingMap));
			return;
		}
		if (LocationUtil.tryShowLocList.length==0){
			return;
		};
		var info=LocationUtil.tryShowLocList.shift();
		var cfg=info.cfg;
		var args=info.args;
		var complete=info.complete;
		var force=info.force;
		var param=args;
		if (!args){
			param=cfg.args;
		}
		LocationUtil.loadingMap[cfg.id]=true;
		console.log("准备加载定位",cfg.id);
		var scriptName=cfg.scrpitName;
		var view;
		var realOpen=true;
		if (!scriptName || scriptName==""){
			console.warn("是否忘记配置定位脚本名字!");
			}else {
			var runTimeClass=LocationUtil.getRuntimeClass(cfg.id);
			if (!runTimeClass){
				delete LocationUtil.loadingMap[cfg.id];
				return;
				}else {
				if (runTimeClass.classTryOpen){
					realOpen=runTimeClass.classTryOpen(param);
				}
			}
		}
		if (realOpen){
			LocationUtil.loadViewRes(cfg,Handler.create(LocationUtil,function(){
				view=new runTimeClass();
				view.locCfg=cfg;
				view.setParam(param);
				delete LocationUtil.loadingMap[cfg.id];
				console.log("定位加载完毕",cfg.id);
				LocationUtil.showView(view,cfg);
				console.log("定位打开已完成",cfg.id);
				complete && complete.runWith(view);
			}));
			}else {
			console.warn("tryOpen 失败",cfg.id);
			delete LocationUtil.loadingMap[cfg.id];
		}
	}

	LocationUtil.showView=function(view,cfg){
		ViewUtil.showView(view,cfg.zOrder,cfg.group);
		LocationUtil.loc2ViewMap[cfg.id]=view;
	}

	LocationUtil.getRuntimeClass=function(id){
		var cfg=ServiceCenter.gameCfgService.getLocationDefine(id);
		var runTimeClass;
		if (cfg){
			var scriptName=cfg.scrpitName;
			runTimeClass=ClassUtils.getRegClass(scriptName)|| ClassUtils.getClass(scriptName);
		}
		if (!runTimeClass){
			console.warn("找不到 runTimeClass",id,scriptName);
		}
		return runTimeClass;
	}

	LocationUtil.getUserInfo=function(){
		var id=VipThink.user.id;
		var userType=VipThink.user.userType;
		var from={id:id,userType:userType};
		return from;
	}

	LocationUtil.injectParam=function(args){
		var param=ObjUtil.deepClone(args)|| {};
		param.userInfo=LocationUtil.getUserInfo();
		return param;
	}

	LocationUtil.loc2ViewMap={};
	LocationUtil.loadingMap={};
	LocationUtil.tryShowLocList=[];
	return LocationUtil;
})()


