/**
*Author:Evans<br/>
*智能字典
*/
//class com.klzz.utils.SmartDictionary
var SmartDictionary=(function(){
	function SmartDictionary(dic){
		this._values=[];
		this._keys=[];
		if (dic){
			for (var i in dic){
				this.set(i,dic[i]);
			}
		}
	}

	__class(SmartDictionary,'com.klzz.utils.SmartDictionary');
	var __proto=SmartDictionary.prototype;
	/**
	*给指定的键名设置值。
	*@param key 键名。
	*@param value 值。
	*/
	__proto.set=function(key,value){
		var index=this.indexOf(key);
		if (index >=0){
			this._values[index]=value;
			return;
		}
		this._keys.push(key);
		this._values.push(value);
	}

	/**
	*将键值设置到指定字典的指定下标（特殊情况下才用）
	*@param key 键名
	*@param value 值
	*@param index 下标
	*/
	__proto.setAt=function(key,value,index){
		this._keys[index]=key;
		this._values[index]=value;
	}

	/**
	*获取指定对象的键名索引。
	*@param key 键名对象。
	*@return 键名索引。
	*/
	__proto.indexOf=function(key){
		var index=this._keys.indexOf(key);
		if (index >=0)return index;
		key=((typeof key=='string'))? Number(key):(((typeof key=='number'))? key.toString():key);
		return this._keys.indexOf(key);
	}

	/**
	*返回指定键名的值。
	*@param key 键名对象。
	*@return 指定键名的值。
	*/
	__proto.get=function(key){
		var index=this.indexOf(key);
		return index < 0 ? null :this._values[index];
	}

	/**获得指定下标的值 */
	__proto.getAt=function(index){
		return this._values[index];
	}

	/**
	*移除指定键名的值。
	*@param key 键名对象。
	*@return 是否成功移除。
	*/
	__proto.remove=function(key){
		var index=this.indexOf(key);
		if (index >=0){
			this._keys.splice(index,1);
			this._values.splice(index,1);
			return true;
		}
		return false;
	}

	/**
	*清除此对象的键名列表和键值列表。
	*/
	__proto.clear=function(){
		this._values.length=0;
		this._keys.length=0;
	}

	/**移除指定下标的值 */
	__proto.removeAt=function(idx){
		if (idx >=0){
			this._keys.splice(idx,1);
			this._values.splice(idx,1);
			return true;
		}
		return false;
	}

	/**
	*获取所有的子元素列表。
	*/
	__getset(0,__proto,'values',function(){
		return this._values;
	});

	__getset(0,__proto,'length',function(){
		return this._keys.length;
	});

	/**
	*获取所有的子元素键名列表。
	*/
	__getset(0,__proto,'keys',function(){
		return this._keys;
	});

	return SmartDictionary;
})()


/**
*View功能类
***/
//class com.biz.utils.ViewUtil
var ViewUtil=(function(){
	function ViewUtil(){}
	__class(ViewUtil,'com.biz.utils.ViewUtil');
	/**
	*节点树根节点
	*/
	__getset(1,ViewUtil,'root',function(){
		return VipThink.viewMgr.root;
	});

	ViewUtil.clear=function(){}
	ViewUtil.showView=function(view,zOrder,group){
		(group===void 0)&& (group=undefined);
		if(group && group !=""){
			ViewUtil.removeViewByGroup(group);
		}
		ViewUtil.tryAppendGroup(group,view);
		view.zOrder=zOrder;
		ViewUtil.root.addChild(view);
	}

	ViewUtil.getViewByGroup=function(group){
		return ViewUtil.group2ViewMap[group];
	}

	ViewUtil.removeViewByGroup=function(group,destroy){
		(destroy===void 0)&& (destroy=true);
		var view=ViewUtil.getViewByGroup(group);
		if(view){
			ViewUtil.doRemoveView(view);
			if(destroy){
				view.destroy();
			}
			delete ViewUtil.group2ViewMap[group];
		}
	}

	ViewUtil.removeView=function(view,destroy){
		(destroy===void 0)&& (destroy=true);
		ViewUtil.doRemoveView(view);
		if(destroy){
			view.destroy();
		}
	}

	ViewUtil.tryAppendGroup=function(group,view){
		if(!group || group==""){
			return;
		}
		ViewUtil.group2ViewMap[group]=view;
	}

	ViewUtil.doRemoveView=function(view,group){
		for(var key in ViewUtil.group2ViewMap){
			var element=ViewUtil.group2ViewMap[key];
			if(view==element){
				ViewUtil.group2ViewMap[key]=undefined;
				delete ViewUtil.group2ViewMap[key];
			}
		}
		view.removeSelf();
		LocationUtil.onRemoveView(view);
	}

	ViewUtil.group2ViewMap={};
	return ViewUtil;
})()


