	VipThink.debugLog=function(clsName,funName,desc,childName,suffix,needExtra){
		(desc===void 0)&& (desc="");
		(childName===void 0)&& (childName="");
		(needExtra===void 0)&& (needExtra=true);
		if (desc && !((typeof desc=='string'))){
			desc=String(desc);
		};
		var str=StringUtil.format("{0}-{1}-{2}-{3}",clsName,funName,childName,desc);
		if (VipThink.viewMgr)
			str+=" || psIdx:["+VipThink.viewMgr.currPageIdx+","+VipThink.viewMgr.currSubviewIdx+"]";
		if (suffix){
			if (!((typeof suffix=='string'))){
				suffix=String(suffix);
			}
			str+=suffix;
		}
		console.debug(str);
	}

	VipThink.logCallee=function(callee,clsName,funName,desc,childName,suffix){
		(clsName===void 0)&& (clsName="");
		(funName===void 0)&& (funName="");
		(desc===void 0)&& (desc="");
		(childName===void 0)&& (childName="");
		(suffix===void 0)&& (suffix="");
		clsName="打印堆栈调用信息,调用者:"+clsName;
		suffix+="\n --------------------------------------------";
		VipThink.debugLog(clsName,funName,desc,childName,suffix);
		var str="";
		var i=1;
		do{
			callee=callee.arguments.callee.caller;
			console.debug(i+": "+VipThink.getFnName(callee)+"\n -------------------------");
			if (i > 6)
				break ;
			i++;
		}
		while (callee);
	}

