//class com.klzz.command.__Command
var __Command=(function(){
	function __Command(type){
		/**优先级 */
		this._priority=1;
		/**类型 */
		this._type=null;
		this.type=type;
	}

	__class(__Command,'com.klzz.command.__Command');
	var __proto=__Command.prototype;
	Laya.imps(__proto,{"com.klzz.command.ICommand":true,"com.klzz.command.ISortable":true,"com.klzz.model.IReuse":true})
	__proto.execute=function(){
		return false;
	}

	__proto.setDetail=function(__param){}
	__proto.toString=function(){
		return null;
	}

	__proto.init=function(__param){}
	__proto.clear=function(){}
	__proto.recover=function(){
		this.clear();
		Pool.recover(this.__className,this);
	}

	__getset(0,__proto,'isValid',function(){
		return false;
	});

	// }
	__getset(0,__proto,'priority',function(){
		return this._priority;
		},function(v){
	});

	__getset(0,__proto,'type',function(){
		return this._type;
		},function(v){
		this._type=v;
		if (this._type)
			this._priority=__Command.PRIORITY_CMD[this._type];
	});

	__Command.TYPE_RENDER_BY_USER="renderByUser";
	__Command.TYPE_RENDER_PASSIVE="renderPassive";
	__Command.TYPE_OP="op";
	__Command.TYPE_NET="net";
	__static(__Command,
	['PRIORITY_CMD',function(){return this.PRIORITY_CMD={
			renderByUser:2,
			renderPassive:1,
			op:1,
			net:0
	};}

	]);
	__Command.__init$=function(){{
			ClassUtils.regClass(RenderByUserCommand.__className,RenderByUserCommand);
			ClassUtils.regClass(RenderPassiveCommand.__className,RenderPassiveCommand);
			ClassUtils.regClass(SocketSendCommand.__className,SocketSendCommand);
		};
	}

	return __Command;
})()


