//class com.klzz.ui.custom.LogPanel.Logs
var Logs=(function(){
	function Logs(){}
	__class(Logs,'com.klzz.ui.custom.LogPanel.Logs');
	Logs.show=function(sp){
		var _logPanelBox=com.klzz.ui.custom.LogPanel.Logs._panel=new LogPanelBox();
		_logPanelBox.name="logPanelBox";
		_logPanelBox.size(sp.width,sp.height);
		sp.addChild(_logPanelBox);
		com.klzz.ui.custom.LogPanel.Logs._panel.update();
		return _logPanelBox;
	}

	Logs.print=function(msg,tag){
		(tag===void 0)&& (tag="");
		if (!msg)
			return;
		console.log(msg);
		com.klzz.ui.custom.LogPanel.Logs.arr.push({tag:tag,msg:msg});
		if (com.klzz.ui.custom.LogPanel.Logs.curTag && com.klzz.ui.custom.LogPanel.Logs.curTag !=tag)
			return;
		com.klzz.ui.custom.LogPanel.Logs.setMsg(msg);
		if (com.klzz.ui.custom.LogPanel.Logs._panel){
			com.klzz.ui.custom.LogPanel.Logs._panel.update();
		}
	}

	Logs.filterMsg=function(tag){
		(tag===void 0)&& (tag="");
		if (com.klzz.ui.custom.LogPanel.Logs.curTag==tag)
			return;
		com.klzz.ui.custom.LogPanel.Logs._msg="";
		com.klzz.ui.custom.LogPanel.Logs.curTag=tag;
		com.klzz.ui.custom.LogPanel.Logs.arr.forEach(function(value,index,array){
			if (!tag || value.tag==tag){
				com.klzz.ui.custom.LogPanel.Logs.setMsg(value.msg);
			}
		});
	}

	Logs.getMsg=function(){
		return com.klzz.ui.custom.LogPanel.Logs._msg;
	}

	Logs.setMsg=function(value){
		if (com.klzz.ui.custom.LogPanel.Logs._msg){
			com.klzz.ui.custom.LogPanel.Logs._msg+="\n\n";
		}
		com.klzz.ui.custom.LogPanel.Logs._msg+=value;
	}

	Logs.clean=function(){
		com.klzz.ui.custom.LogPanel.Logs._msg="";
		com.klzz.ui.custom.LogPanel.Logs.arr=[];
	}

	Logs._msg="";
	Logs.curTag="";
	Logs.arr=[];
	Logs._panel=null;
	return Logs;
})()


