/**滤镜支持
*@author Evans
*/
//class com.klzz.ui.KlFilter
var KlFilter=(function(){
	function KlFilter(){}
	__class(KlFilter,'com.klzz.ui.KlFilter');
	KlFilter.extend=function(cls){
		var klfilter=KlFilter;
		var clsProtoType=cls.prototype;
		var oriFilterDes=Object.getOwnPropertyDescriptor(clsProtoType,'filters');
		Object.defineProperty(clsProtoType,"filters",{
			"get":oriFilterDes.get,
			'set':function (value){
				if (this.sync!==undefined){
					var result=klfilter.beforeSetFilters(this,value);
					this.sync('filters',result[0],result[1]);
					oriFilterDes.set.call(this,result[2]);
					klfilter.afterSetFilters(this,result[1]);
					}else {
					oriFilterDes.set.call(this,value);
				}
			}
		});
		return cls;
	}

	KlFilter.getFilterByInfo=function(info){
		if (!info || (!info._filterType && !info.mat))return null;
		var result;
		var ftype=info._filterType;
		if (ftype===0x08){
			result=new GlowFilter(info.colorStr,info.blur,info.offX,info.offY,info.outlineSize);
			}else if (ftype===0x10){
			result=new BlurFilter(info.strength);
			}else if (ftype===0x20 || (!ftype && info.mat)){
			info._filterType=0x20;
			result=new ColorFilter(info.mat);
		}
		return result;
	}

	KlFilter.getFilterInfo=function(filter,createNew){
		(createNew===void 0)&& (createNew=true);
		if (!filter)return null;
		function getFinfo (createNew){
			var res=null;
			createNew ? (res={}):(res=KlFilter._tmpFilterInfo);
			ObjUtil.clearObj(res);
			return res;
		};
		var finfo=null;
		if (filter.type===0x08){
			var gf=filter;
			finfo=getFinfo(createNew);
			return ObjUtil.extendObj(finfo,{
				_filterType:gf.type,
				colorStr:gf.colorStr,
				blur:gf.blur,
				offX:gf.offX,
				offY:gf.offY,
				outlineSize:gf["_sv_outlineSize"]
			});
			}else if (filter.type===0x10){
			var bf=filter;
			finfo=getFinfo(createNew);
			return ObjUtil.extendObj(finfo,{_filterType:bf.type,strength:bf.strength });
			}else if (filter.type===0x20){
			var cf=filter;
			finfo=getFinfo(createNew);
			return ObjUtil.extendObj(finfo,{_filterType:cf.type,mat:cf.mMat });
		}
		return finfo;
	}

	KlFilter.beforeSetFilters=function(target,value){
		if (!target.hasOwnProperty("_filtersInfo")){
			Object.defineProperty(target,'_filtersInfo',{
				value:null,
				writable:true
			});
		};
		var fi=target["_filtersInfo"];
		value && !value.length && (value=null);
		var valueInfo=null;
		if (value){
			if (value[0]._filterType || value[0].mat){
				valueInfo=value;
				value=[];
				valueInfo.forEach(function(finfo){
					var f=com.klzz.ui.KlFilter.getFilterByInfo(finfo);
					f && value.push(f);
				});
				}else {
				valueInfo=[];
				value.forEach(function(filter){
					var fi=com.klzz.ui.KlFilter.getFilterInfo(filter);
					fi && valueInfo.push(fi);
				});
			}
		}
		return [fi,valueInfo,value];
	}

	KlFilter.afterSetFilters=function(target,filtersInfo){
		var fi=target["_filtersInfo"];
		(fi!==undefined)&& (target["_filtersInfo"]=filtersInfo);
	}

	KlFilter._tmpFilterInfo={};
	return KlFilter;
})()


