	/**
	*罗博手写板 数据
	*@param param param.args.data {robo_y:Number,robo_x:Number,robo_suspending:Number}
	*/
	__proto.setRobotData=function(param){
		if (param && param.args && param.args.data){
			var obj_robot=param.args.data;
			var strength=Number(obj_robot.robo_suspending);
			var x=Number(obj_robot.robo_x);
			var y=Number(obj_robot.robo_y);
			strength=Math.ceil((strength/1023)*99);
			if (isNaN(x)|| isNaN(y)|| (x < 0 || y < 0)){
				console.debug("DefaultNative","RoBo写字板无效数据",obj_robot);
				return;
			}
			if(x==0 && y==0 && strength==0){
				console.debug("DefaultNative","笔离开手写板");
				KlEventCenter.event("robotpen_release");
				}else{
				KlEventCenter.event("robotpen_move",{x:x,y:y,strength:strength});
			}
		}
	}

