	// private var _addScoreExcute:Boolean=false;
	__proto.addScore=function(idList,numList,callByNative,excuteNow,groupId,pageIdx,extend){
		(callByNative===void 0)&& (callByNative=false);
		(excuteNow===void 0)&& (excuteNow=false);
		(groupId===void 0)&& (groupId=-1);
		if (callByNative){
			if (GlobalModel.user.userType==1 && !excuteNow){
				idList=idList || this._us.studentIDList;
				if (!idList){
					return;
				}
				if (!this._megerDic){
					this._megerDic={};
				}
				for (var j=0;j < idList.length;j++){
					var id=idList[j];
					if (!this._megerDic[id]){
						this._megerDic[id]=0;
					}
					if (numList && numList.length){
						this._megerDic[id]+=numList[j];
					}
					else{
						this._megerDic[id]+=1;
					}
				};
				var timeDelay=0;
				var timeInterval=200;
				if (this._startScoreTs > 0){
					var timeStep=Browser.now()-this._startScoreTs;
					if (timeStep >=timeInterval){
						timeDelay=0;
					}
					else{
						timeDelay=timeInterval-timeStep;
					}
				}
				else{
					this._startScoreTs=Browser.now();
					timeDelay=timeInterval;
				}
				if (timeDelay > 0){
					Laya.timer.clear(this,this.addToStudentSpeScore);
					Laya.timer.once(timeDelay,this,this.addToStudentSpeScore,[groupId,pageIdx]);
				}
				else{
					Laya.timer.clear(this,this.addToStudentSpeScore);
					this.addToStudentSpeScore(groupId,pageIdx);
				}
				return;
			}
		}
	}

	__proto.addScoreCallToNative=function(idList,numList,groupId,pageIdx){
		(groupId===void 0)&& (groupId=-1);
		this.sendToNative("addScore",{idList:idList,numList:numList,groupId:groupId,pageIdx:pageIdx,extend:{sendByTask:this.sendScoreByTask}});
		this.sendScoreByTask && (this.sendScoreByTask=false);
	}

	__proto.addToStudentSpeScore=function(groupId,pageIdx){
		(groupId===void 0)&& (groupId=-1);
		if (!this._megerDic){
			this._startScoreTs=0;
			return;
		};
		var idList=[];
		var numList=[];
		for (var id in this._megerDic){
			idList.push(Number(id));
			numList.push(this._megerDic[id]);
		}
		this._us.addStudentSpeScore(idList,numList,groupId,pageIdx);
		this._megerDic=null;
		this._startScoreTs=0;
		this.doSynchroStar();
	}

