	/**处理获取启动参数回调，注意这里没有this域 */
	__proto.onLaunchParam=function(result){
		if ((typeof result=='string')){
			if (result==""){
				console.error("DefaultNative","Launch param is null.");
				return;
			}
			result=StringUtil.jsonParse(result);
		}
		if (!((typeof result=='object'))){
			console.error("DefaultNative","Launch param is not an object.");
			return;
		}
		result.socketInfo=result.socketInfo || {};
		GameMgr.instance.init(result);
		Laya.timer.callLater(null,function(_result){
			_result=_result || {};
			if (!_result.course)
				_result.course=StringUtil.getUrlParam().course;
			if (!_result.star && StringUtil.getUrlParam().star !=undefined){
				_result.star=parseInt(StringUtil.getUrlParam().star);
			}
			if (!_result.currentStar && StringUtil.getUrlParam().currentStar !=undefined){
				_result.currentStar=parseInt(StringUtil.getUrlParam().currentStar);
			}
			_result.type=NativeAPI.instance.type;
			NativeAPI.instance.handleLaunchParam(result);
			NativeAPI.hdrGetLaunchParam && NativeAPI.hdrGetLaunchParam.runWith([NativeAPI.instance,result]);
			RoomManager.instance.init();
		},[result]);
	}

