	/**处理用户状态的事件 */
	__proto.onUserStatusEvt=function(data){
		var action=data.action;
		if (!action || !data.users)
			return;
		var i=0,len=0;
		var myidx=data.users.indexOf(this.me.id);
		var changeme=myidx >=0;
		var myval=changeme ? data.nvalues[myidx] :null;
		var trueIdx=data.nvalues.indexOf(true);
		var trueUserID=(trueIdx >=0)? data.users[trueIdx] :0;
		if (action=="logout" && changeme){
			this.logout();
		}
		else if (action=="setOnAir"){
			var idx=0;
			if (data.users.length > 1){
				if (data.users.length > 2)
					console.warn(this.type,"上下台为啥会有2个以上的用户被影响？");
				for (i=0,len=data.nvalues.length;i < len;i++){
					if (data.nvalues[i] > 0){
						idx=i;
						break ;
					}
				}
			}
			this.setOnAir({uid:data.users[idx],screenType:data.nvalues[idx]});
		}
		else if (action=="setMuted"){
			this.setMuted(data.users[0],data.nvalues[0]);
		}
		else if (action=="setAuthorUser"){
			this.setAuthorUser(trueUserID || 0);
		}
		else if (action=="setTPUser"){
			this.setTPUser(trueUserID || 0);
		}
		else if (action=="addScore"){
			var cvalues=[];
			for (i=0,len=data.users.length;i < len;i++){
				cvalues.push(data.nvalues[i]-data.ovalues[i]);
			}
			this.addScoreCallToNative(data.users,cvalues,data.groupId);
		}
		else if (action=="setWatchers"){
		}
		else if (action=="setWatchingUser"){
			changeme && GlobalModel.setWatchUser(data.nvalues[0]);
		}
	}

