	/**应用端通知课件跳转到指定的关卡 */
	__proto.jumpToPage=function(param,callByNative){
		(callByNative===void 0)&& (callByNative=false);
		if (callByNative){
			if (param && param.args && param.args.level && param.args.subj){
				var level=param.args.level;
				var subj=param.args.subj;
				var sync=param.args.sync ? 1 :0;
				if ((typeof level=='string'))
					level=parseInt(level)
				if ((typeof subj=='string'))
					subj=parseInt(subj);
				if (level > VipThink.viewMgr.mainView.pageNum || level <=0){
					level=VipThink.viewMgr.currPageIdx;
					subj=VipThink.viewMgr.currSubviewIdx;
					console.error("jumpToPage接口，不存在level："+level);
				}
				else{
					level--;
					var page=VipThink.viewMgr.mainView.pageCfgList;
					var obj=page[level];
					var subViews=obj.subViews;
					if (subViews && subViews.length > 1){
						if (subj > subViews.length || subj <=0){
							subj=VipThink.viewMgr.currSubviewIdx;
							console.error("jumpToPage接口，不存在subj："+subj);
						}
						else{
							subj--;
						}
					}
					else{
						subj=0;
					}
				}
				if (level !=VipThink.viewMgr.currPageIdx || subj !=VipThink.viewMgr.currSubviewIdx){
					if (level !=VipThink.viewMgr.currPageIdx){
						VipThink.resetPageSync=1;
					}
					else{
						VipThink.resetPageSync=sync;
					}
					VipThink.viewMgr.mainView.activeResetPage=true;
					VipThink.viewMgr.setCurrPageIdx(level,subj,true);
				}
			}
		}
		else{
			this.sendToNative("jumpToPage",param);
		}
	}

