/**
*Author:Evans<br/>
*Desc:socket消息处理器
*/
//class com.klzz.net.SocketHandler extends laya.events.EventDispatcher
var SocketHandler=(function(_super){
	function SocketHandler(){
		/**socket */
		this.socket=null;
		/**状态主题 */
		this._ss=null;
		/**是否禁止发送socket消息，AI录播预览的时候 禁止 */
		this.prohibitSocket=false;
		SocketHandler.__super.call(this);
		if (SocketHandler.instance){
			console.error("__SocketHandler","The instance must be only one.");
			return;
		}
		SocketHandler.instance=this;
	}

	__class(SocketHandler,'com.klzz.net.SocketHandler',_super);
	var __proto=SocketHandler.prototype;
	/**
	*初始化
	*@param socket Socket
	*@param ss Socket状态主题
	*/
	__proto.__init__=function(socket,ss){
		this.socket=socket;
		this._ss=ss;
		if (socket && this._ss){
			this._ss.socket=socket;
			socket.evtDispatcher.on("message",this,this.onSocketMsg);
			socket.evtDispatcher.on("changed",this,this.onSocketStatusChanged);
		}
		window.addEventListener('online',function(){console.debug('网络重连了！');KlEventCenter.event('online')});
		window.addEventListener('offline',function(){console.error('网络断开了！');KlEventCenter.event('offline')});
		return this;
	}

	/**
	*发送数据给服务器
	*@param ptl 协议号
	*@param data:*数据
	*@param handler 回调处理
	*@param hdrKey 回调key。没的话就用protocol作为key
	*@return
	*/
	__proto.sendMsg=function(ptl,data,handler,hdrKey){
		if(VipThink.TEACHER_PREPARE_LESSONS){
			LocalService.instance.handleSocket(ptl,data,handler,hdrKey);
			return;
		}
		if (this.prohibitSocket)
			return;
		this.socket.send(ptl,data,handler,hdrKey);
	}

	/**
	*当收到socket消息
	*@param data socket消息数据({cmd,data:{state...}})
	*/
	__proto.onSocketMsg=function(data){
		this.event("message",data);
	}

	/**
	*当socket状态改变
	*@return
	*/
	__proto.onSocketStatusChanged=function(data){
		this._ss.changed=data;
	}

	SocketHandler.instance=null;
	return SocketHandler;
})(EventDispatcher)


/**
*Author:Evans<br/>
*Desc:广播消息处理器
*/
//class com.biz.net.NoticeHandler extends laya.events.EventDispatcher
var NoticeHandler=(function(_super){
	function NoticeHandler(scHdr){
		this._socketHdr=null;
		/**跳过是否自己发出的协议的检查 */
		this._IGNORE_CHECK_PTL=[
		Protocol.SAVE_DATA[1],
		"CloseUserResult"];
		NoticeHandler.__super.call(this);
		this._socketHdr=scHdr;
		this._socketHdr.on("message",this,this.onSocketMsg);
	}

	__class(NoticeHandler,'com.biz.net.NoticeHandler',_super);
	var __proto=NoticeHandler.prototype;
	/**处理Socket消息 */
	__proto.onSocketMsg=function(data){
		var rdata=data && data.data;
		if (!rdata)
			return;
		if (CustomRoomDataUtil.hasProtocol(data.cmd)){
			CustomRoomDataUtil.onReceiveInfo(data.cmd,rdata);
		}
		else if (data.cmd=="Ping"){
			VipThink.setServerTime(data.data.serverTime);
		}
		if (VipThink.OPEN_PLAY_BACK_RECORD){
			KlEventCenter.event("recordData",[data]);
		}
		if (rdata && rdata.userId==VipThink.user.id && this._IGNORE_CHECK_PTL.indexOf(data.cmd)< 0)
			return;
		var editor=rdata.userId;
		if ("CloseUserResult"==data.cmd){
			VipThink.socketHdr.socket.onRelogin();
		}
		else if (data.cmd=="EnterUser" || data.cmd=="LeftRoom"){
			if (!data.callLater){
				data.callLater=true;
				if (!VipThink.userStatus.preHandleUser){
					VipThink.userStatus.preHandleUser=rdata.userVO;
				}
				else{
					if ((VipThink.userStatus.preHandleUser instanceof Array))
						VipThink.userStatus.preHandleUser.push(rdata.userVO);
					else
					VipThink.userStatus.preHandleUser=[VipThink.userStatus.preHandleUser,rdata.userVO];
				}
				rdata.userVO=VipThink.userStatus.preHandleUser;
				Laya.timer.frameOnce(1,this,this.onSocketMsg,[data]);
			}
			else if (rdata.roomId==VipThink.user.currentRoomId){
				VipThink.userStatus.whenUserInoutRoom(rdata.userVO || rdata,data.cmd=="LeftRoom");
				VipThink.userStatus.preHandleUser && (VipThink.userStatus.preHandleUser=null);
			}
		}
		else if (data.cmd=="IsOnlineResult"){
			VipThink.userStatus.whenUserOnlineStatus(rdata.userIds,rdata.userStatuses);
		}
		else if (data.cmd==Protocol.BROADCAST_MSG[1]){
			if (rdata.state !=0){
				console.error("BroadcastHandler","What a msg?!",rdata);
				return;
			}
			rdata.content=StringUtil.jsonParse(rdata.content);
			var content=rdata.content;
			function logError (msg,report){
				(report===void 0)&& (report=true);
				if (report){
					Reporter.reportData(1,msg,null,{logger:console.warn});
				}
			}
			if (!content){
				logError("NoticeHandler - onSocketMsg - content is undefined");
				return;
			}
			if (content && content.action !="EnterRoom" && !VipThink.isAI){
				if (!content.roomID || !content.roomID.length || content.roomID=="0"){
					logError("NoticeHandler - socket数据串房，收到其他房间的广播消息,cotent:"+JSON.stringify(content),false);
					return;
				}
				if (VipThink.user){
					if (!VipThink.user.currentRoomId || !VipThink.user.currentRoomId.length){
						logError("NoticeHandler - VipThink.user.currentRoomId is null,未进入课室",false);
						return;
					}
					if (content.roomID !=VipThink.user.currentRoomId){
						logError("NoticeHandler - socket数据串房，收到其他房间的广播消息,cotent:"+JSON.stringify(content));
						return;
					}
				}
			};
			var action=content.action;
			if (action=="renderByUser" || action=="renderPassive"){
				VipThink.transMgr.handleTrans(content,true);
			}
			else if (action=="reset"){
				VipThink.viewMgr.reset(content.active,content.param);
			}
			else if (action=="kickout"){
				VipThink.userStatus.logout();
			}
			else if (action=="doTrans"){
				TransManager.doTrans(content.transType,null,[content]);
			}
			else if (action==Protocol.ENTER_ROOM[0]){
				console.log("课件log：NoticeHandler-action:EnterRoo,rdata=",data);
			}
			else{
				this.event("message",data);
			}
		}
		else if (data.cmd==Protocol.CLEAR_CACHE_DATA[1]){
			var ruleStr;
			for(var $each_ruleStr in rdata.rules){
				ruleStr=rdata.rules[$each_ruleStr];
				var rule=StringUtil.jsonParse(ruleStr);
				MyTransMgr.handleServerNotify(rule,editor,data.cmd);
			}
		}
		else if (data.cmd==Protocol.SAVE_DATA[1]){
			if (!VipThink.userStatus.getUserByID(rdata.userId)&& !VipThink.isAIPlay)
				return;
			if (rdata.key=="global"){
				if ((typeof rdata.value=='string'))
					rdata.value=StringUtil.jsonParse(rdata.value);
				if (!VipThink.isAI){
					if (rdata.value.teachId !=undefined){
						if (VipThink.userStatus && VipThink.userStatus.teacher){
							if (VipThink.userStatus.teacher.id !=rdata.value.teachId){
								return console.error("NoticeHandler - onSocketMsg - 收到的修改房间数据的消息来源非本房间老师, 本房间teacherId:"+VipThink.userStatus.teacher.id+";rdata.value.teachId:"+rdata.value.teachId);
							}
						}
						delete rdata.value.teachId;
					}
					else{
						var teaId=null;
						if (VipThink.userStatus && VipThink.userStatus.teacher){
							teaId=VipThink.userStatus.teacher.id;
						}
						console.warn("NoticeHandler - onSocketMsg - 收到的修改房间数据的消息来源老师id是空, 本房间teacherId:"+teaId);
					}
				}
				GlobalModel.onGlobalDataResult(rdata.value);
			}
		}
		else if (data.cmd==Protocol.UPDATE_CACHE_DATA[1]){
			if (!VipThink.userStatus.getUserByID(rdata.userId)&& !VipThink.isAIPlay){
				return;
			}
			if (!GlobalModel.isInRoom()){
				return;
			};
			var cdata=GetUserCacheFilter.convertResult(rdata);
			var dl=cdata.data;
			if (dl && dl.length > 0){
				for (var i=0,len=dl.length;i < len;i++){
					var de=dl[i];
					var key=de.key;
					if (de.status==0){
						if (!MyTransMgr.handleServerNotify(de,editor,data.cmd))
							console.warn("NoticeHandler","不能处理的数据。");
					}
					else{
						console.warn("NoticeHandler",de.msg);
					}
				}
			}
		}
	}

	return NoticeHandler;
})(EventDispatcher)


