		this.cmds=["next","unLock","onStage","initialData","insertPlayRecordCmd","recover"];
		this._levelClickCount=0;
		this._clickCount=0;
		//接收到sendData事件的时间
		this._receiveSendDataTime=0;
		//关卡开始播的时间
		this._startPlayTs=NaN;
		//是否播放中
		this.PLAYING=false;
		//学生答题正确了，弹出乐迪动画了
		this._studentFinish=false;
		// 录制的数据的类型 1：socket数据 2：正课回放数据
