/**动态难度分层配置处理器
*@author Evans
*/
//class com.biz.alls.ALLSCfgHandler extends com.biz.common.gameset.DefaultCfgHandler
var ALLSCfgHandler=(function(_super){
	function ALLSCfgHandler(){
		ALLSCfgHandler.__super.call(this);;
	}

	__class(ALLSCfgHandler,'com.biz.alls.ALLSCfgHandler',_super);
	var __proto=ALLSCfgHandler.prototype;
	__proto.getPageCfg=function(config){
		var aconfig=this.launchParam.ALLS;
		if (aconfig && aconfig.diff==="ALL"){
			return _super.prototype.getPageCfg.call(this,config);
		};
		var diffList=config.diff_config;
		if (!diffList && config.pages){
			diffList=[];
			config.pages.forEach(function(v){
				if (!v.alls_diff){
					diffList.push(0);
					}else if (v.alls_diff){
					diffList.push(v.alls_diff);
				}
			});
		}
		if (!aconfig || !diffList)return _super.prototype.getPageCfg.call(this,config);
		var diffPath=aconfig.diffPath;
		if (!diffPath){
			if (!aconfig.diff){
				console.warn("ALLS参数里缺少diffPath/diff，将以默认难度（A）启动");
				return _super.prototype.getPageCfg.call(this,config);
			}
			diffPath=[aconfig.diff];
		};
		var pagePerDiff=aconfig.diffPath ? (aconfig.pagePerDiff || 1):0;
		if (pagePerDiff > 1){
			var tmpDiffPath=[];
			diffPath.forEach(function(v){
				for (var i=0;i<pagePerDiff;i++){
					tmpDiffPath.push(v);
				}
			});
			diffPath=tmpDiffPath;
		};
		var currDiffIdx=0;
		var finalPageIdx=[];
		var needToPassB=false;
		diffList.forEach(function(v,idx){
			if (!v){
				finalPageIdx.push(idx);
				}else {
				if (currDiffIdx >=diffPath.length){
					console.warn("ALLSCfgHandler.getPageCfg","难度下标越界","diffPath:",diffPath,"currDiffIdx:",currDiffIdx,"pagePerDiff:",pagePerDiff);
					currDiffIdx=diffPath.length-1;
				};
				var currDiff=(diffPath [currDiffIdx]).toUpperCase();
				v=v.toUpperCase();
				if (v.includes(currDiff)){
					if (currDiff!=="B" || !needToPassB){
						finalPageIdx.push(idx);
						if (v.includes("A"))needToPassB=true;
						if (pagePerDiff){
							currDiffIdx++;
						}else {}
					}
					if (currDiff==="B" && needToPassB)needToPassB=false;
				}
			}
		});
		return ViewCfgVO.handleViewConfig(config.pages,config.extConfig,finalPageIdx);
	}

	return ALLSCfgHandler;
})(DefaultCfgHandler)


