	/**
	*设置用户属性（默认马上提交）
	*@param id 用户ID
	*@param key 数据 key
	*@param value:*值
	*@param setOther 将其他用户设置为的值
	*@param commitNow 是否马上提交
	*/
	__proto.setUserProp=function(id,key,value,action,setOther,commitNow){
		(setOther===void 0)&& (setOther="undefined");
		(commitNow===void 0)&& (commitNow=true);
		console.debug("setUserProp id:%d, key:%s, action:%s",id,key,action);
		var actionName=action || "default";
		if (!this._toUpdateInfo[actionName]){
			this._toUpdateInfo[actionName]=[];
		};
		var updateIDList=this._toUpdateInfo[actionName];
		var _self=this;
		function setValue (uvo,key,value){
			uvo[key]=value;
			if (!updateIDList.includes(uvo.id)){
				updateIDList.push(uvo.id);
			}
		};
		var allList=this.getAllUserList(true);
		var uvo;
		for(var $each_uvo in allList){
			uvo=allList[$each_uvo];
			if (setOther!=="undefined"){
				if (id !=uvo.id && uvo[key]){
					setValue(uvo,key,setOther);
				}
			}
			if (id==uvo.id && uvo[key] !=value){
				setValue(uvo,key,value);
			}
		}
		if (commitNow){
			this.handleUpdateIDList();
			}else {
			Laya.timer.frameOnce(1,this,this.handleUpdateIDList);
		}
	}

	/**设置当前授权用户 */
	__proto.setAuthorUser=function(id){
		this.setUserProp(id,"isAuthor",true,"setAuthorUser",false);
	}

