	/**处理返回的用户数据 */
	__proto.onUserDataUpdated=function(action,list){
		if(action=="addScore"){
			console.debug("加分返回玩家数据",list);
		}
		if (list){
			var evts={};
			for (var i=0,len=list.length;i < len;i++){
				var data=list[i];
				if (data.value){
					var act=action && data.value.action;
					var prop=UserStatus.PROP_MATCH[act] || act;
					var groupId=data.value.groupId;
					var uvo;
					uvo=this.getStudentByID(data.uId)|| this.getWatcherByID(data.uId);
					if (this._teacher && data.uId==this._teacher.id){
						uvo=this._teacher;
						this.changeType="teacher";
					}
					else if (uvo && uvo==this.getStudentByID(data.uId)){
						this.changeType="student";
					}
					else if (uvo && uvo==this.getWatcherByID(data.uId)){
						this.changeType="watcher";
					}
					if (uvo){
						uvo.update(data.value,UserStatus.PROP_MATCH[action]);
						if (act){
							if (!evts[act]){
								evts[act]={prop:prop,users:[],ovalues:[],nvalues:[],groupId:groupId};
							};
							var evtObj=evts[act];
							evtObj.users.push(uvo.id);
							if (data.value.oval !=undefined){
								evtObj.ovalues.push(data.value.oval);
							}
							evtObj.nvalues.push(uvo[prop]);
						}
					}
					else{
						console.warn("UserStatus","这是哪来的用户");
						continue ;
					}
				}
				else{
					console.warn("UserStatus","怎么会没有value？！data: ",data)
				}
			}
			for (var k in evts){
				var evtObj2=evts[k];
				this.event("changed",{action:k,prop:evtObj2.prop,users:evtObj2.users,ovalues:evtObj2.ovalues,nvalues:evtObj2.nvalues,groupId:evtObj2.groupId});
			}
		}
	}

