	/**
	*处理同步逻辑，切关，页面中的组件同步，都走这里
	*@param comp 要同步的组件
	*@param prop 同步属性
	*@param oriVal:*属性旧值
	*@param toVal:*属性新值
	*@param cls 类
	*@return void
	*/
	__proto.handleSync=function(comp,prop,oriVal,toVal,cls){
		if (!comp.displayedInStage)
			return;
		var syncType=SyncAssist.getSyncCompType(comp);
		if (!syncType)
			return;
		if (!SyncAssist.hasRecover)
			return;
		if (this._gettingChlData && prop !="currIndices")
			return;
		var isc=(comp).unSyncProps;
		if (isc && isc.split(",").indexOf(prop)!=-1){
			return;
		};
		var transType=SyncAssist.getSyncTransType(syncType);
		var data;
		if (syncType==4){
			VipThink.debugLog("MyViewManager","handleSync","pageIdx:"+this.currPageIdx+",viewIdx:"+this.currSubviewIdx);
			data={pageIdx:this.currPageIdx,viewIdx:this.currSubviewIdx};
		}
		else if (syncType==1){
			if (this.currPage.status !="prepared")
				return;
			var xpath=this.getXpathByComp(comp);
			if (!xpath || xpath.indexOf("empty name")>-1){
				console.warn("ViewManager","Comp's xpath error");
				return;
			}
			if (oriVal==toVal){
				var skey=SyncAssist.dicComp.getKeyByProp("xpath",xpath);
				if (!skey || SyncAssist.dicComp.getProp(skey,prop)==toVal)
					return;
			}
			data={
				xpath:xpath,propName:prop,oriVal:oriVal,toVal:toVal};
		}
		else{
			if (oriVal==toVal)
				return;
			data={propName:prop,oriVal:oriVal,toVal:toVal};
		}
		data.comp=comp;
		data.type=transType;
		data && Klzz.transMgr.handleTrans(data);
	}

