	__proto.getXpathByComp=function(comp,addPagePrefix){
		(addPagePrefix===void 0)&& (addPagePrefix=false);
		var syncType=SyncAssist.getSyncCompType(comp);
		if (syncType==1)
			return _super.prototype.getXpathByComp.call(this,comp,addPagePrefix);
		else
		return syncType+"."+comp.name;
	}

