	/**
	*用还原数据还原视图
	*/
	__proto.recoverByData=function(data){
		if (!data)
			return;
		if (SocketDataDictionary.mySwitch){
			if (data.comp && data.comp.length > 0){
				for (var i=0;i < data.comp.length;i++){
					var item=data.comp[i];
					var itemStr=JSON.stringify(item);
					itemStr=this.decode(itemStr);
					data.comp[i]=JSON.parse(itemStr);
				}
			}
		}
		if (VipThink.OPEN_PLAY_BACK_RECORD)
			this.event("recoverData",data);
		this._gettingChlData=false;
		VipThink.debugLog("MyViewManager","recoverByData",("执行还原操作，currPage:"+(this.currPage ? 1 :"null")+",currPage.status:"+(this.currPage ? this.currPage.status :"null")+",isAiAndIsPlaying:"+VipThink.isAiAndIsPlaying));
		if (VipThink.isAiAndIsPlaying){
			var r=SyncAssist.recoverByData(data,this.currPage ? this.currPage.status :null);
			if (r){
				VipThink.debugLog("MyViewManager","recoverByData","step1");
				_super.prototype.reset.call(this);
			}
			else{
				if (!this.currPage){
					VipThink.debugLog("MyViewManager","recoverByData","step2");
					this.jumpToCurrPage();
				}
			}
		}
		else{
			var currLevel=this.currPageIdx;
			var currSubj=this.currSubviewIdx;
			VipThink.debugLog("MyViewManager","recoverByData","data.currIndices:"+data.currIndices+", mainview.currIndices:"+this.mainView.currIndices+" GloablModel.currProg:"+GlobalModel.currProg);
			if (data.currIndices && ((data.currIndices[0])instanceof Array)){
				data.currIndices=data.currIndices[data.currIndices.lenght-1];
			}
			if (data.currIndices && data.currIndices.length==2){
				SwitchQuestionCtr.changePage(data.currIndices);
				if (currLevel !=data.currIndices[0] || currSubj !=data.currIndices[1]){
					VipThink.debugLog("MyViewManager","recoverByData","step3");
					this.jumpToCurrPage(false,data.currIndices[0],data.currIndices[1]);
				}
				else if (currLevel==data.currIndices[0] || currSubj==data.currIndices[1]){
					var r1=SyncAssist.recoverByData(data,this.currPage ? this.currPage.status :null);
					if (r1){
						VipThink.debugLog("MyViewManager","recoverByData","step4");
						_super.prototype.reset.call(this);
					}
					else{
						if (!this.currPage){
							VipThink.debugLog("MyViewManager","recoverByData","step5");
							this.jumpToCurrPage();
						}
					}
					return;
				}
				else if (currLevel !=GlobalModel.currProg[0] || currSubj !=GlobalModel.currProg[1]){
					VipThink.debugLog("MyViewManager","recoverByData","step6");
					this.jumpToCurrPage(false,data.currIndices[0],data.currIndices[1]);
				}
				VipThink.debugLog("MyViewManager","recoverByData","step7");
				SyncAssist.recoverByData(data,this.currPage ? this.currPage.status :null);
				return;
			}
			if (!data.currIndices || data.currIndices.length==0){
				if (currLevel !=GlobalModel.currProg[0] || currSubj !=GlobalModel.currProg[1]){
					VipThink.debugLog("MyViewManager","recoverByData","step8");
					this.jumpToCurrPage();
					SyncAssist.recoverByData(data,this.currPage ? this.currPage.status :null);
				}
				else{
					var r2=SyncAssist.recoverByData(data,this.currPage ? this.currPage.status :null);
					if (r2){
						VipThink.debugLog("MyViewManager","recoverByData","step9");
						_super.prototype.reset.call(this);
					}
					else{
						if (!this.currPage){
							VipThink.debugLog("MyViewManager","recoverByData","step10");
							this.jumpToCurrPage();
						}
					}
				}
				return;
			}
			if (!this.currPage){
				VipThink.debugLog("MyViewManager","recoverByData","step11");
				this.jumpToCurrPage();
			}
		}
	}

