	/**
	*遍历获取当前游戏界面所有的KlSkelton1和KlTweenBox
	*/
	__proto.ergodicComp=function(comp,arr){
		if (!comp || !comp.numChildren)
			return [];
		if (!arr)
			arr=[];
		for (var i=0;i < comp.numChildren;i++){
			var c=comp.getChildAt(i);
			if (c.numChildren){
				this.ergodicComp(c,arr);
			}
			else{
				if ((c instanceof com.klzz.ui.KlSkeleton1 )|| (c instanceof com.klzz.ui.KlTweenBox )){
					arr.push(c);
				}
			}
		}
		return arr;
	}

	/**
	*解码
	*/
	__proto.decode=function(value){
		for (var j=SocketDataDictionary.decodeDictionary.length-1;j >=0;j--){
			var toReplayceStr=SocketDataDictionary.decodeDictionary[j];
			var replayceStr=SocketDataDictionary.codeDictionary[j];
			value=value.replace(new RegExp(toReplayceStr,'g'),replayceStr);
		}
		return value;
	}

	/**
	*播放视频
	*@param videoUrl 视频地址
	*@param type 1：播放视频 0：销毁视频 当type为0时，可以不设置videoUrl参数
	*@param autoPlay 是否自动播放 1：自动， 0：不自动
	*@param hide 播放完是否隐藏 1、隐藏，0：不隐藏
	*@param fill 是否全屏播放 1、全屏 ， 0：不全屏
	*@param videoX 视频x坐标 默认0
	*@param videoY 视频y坐标 默认0
	*@param videoWidth 视频宽 默认1920
	*@param videoHeight 视频高 默认1080
	*@return [description]
	*/
	__proto.playVideo=function(videoUrl,type,autoPlay,hide,fill,videoX,videoY,videoWidth,videoHeight){
		(type===void 0)&& (type=1);
		(autoPlay===void 0)&& (autoPlay=0);
		(hide===void 0)&& (hide=0);
		(fill===void 0)&& (fill=1);
		(videoX===void 0)&& (videoX=0);
		(videoY===void 0)&& (videoY=0);
		(videoWidth===void 0)&& (videoWidth=1920);
		(videoHeight===void 0)&& (videoHeight=1080);
		if (!VipThink.currView){
			console.error("MyViewManager playVideo VipThink.currView is undefined");
			return;
		}
		VipThink.debugLog("MyViewManager","playVideo","videoUrl is undefined");
		if (type){
			if (!videoUrl){
				console.error("MyViewManager playVideo videoUrl is undefined");
				return;
			}
			type=type ? "video" :"nomal";
			if (videoUrl.indexOf("http://")!=-1 || videoUrl.indexOf("https://")!=-1){
				this.sendUrl(videoUrl,type,autoPlay,hide,fill,videoX,videoY,videoWidth,videoHeight);
			}
			else{
				var courseUrl=VipThink.config.courseCfg ? VipThink.config.courseCfg.url :null;
				var url;
				if (videoUrl.indexOf("share/animation/")!=-1){
					url=videoUrl;
				}
				else{
					url=courseUrl ? (courseUrl+'/'+videoUrl):videoUrl;
				};
				var fullUrl=URL.formatURL(url);
				if (fullUrl && fullUrl.indexOf("/lessons/")==-1 && fullUrl.indexOf("share/animation")==-1){
					this.sendUrl(fullUrl,type,autoPlay,hide,fill,videoX,videoY,videoWidth,videoHeight);
				}
				else{
					var customUrl=URL.customFormat(url);
					if (customUrl){
						this.sendUrl(customUrl,type,autoPlay,hide,fill,videoX,videoY,videoWidth,videoHeight);
					}
					else{
						console.error('videoView customUrl is undefined');
					}
				}
			}
		}
		else{
			this.sendUrl("","nomal");
			this.clearLocalVideo();
		}
	}

