	/**
	*
	*@return 返回一个角度 三个点之间的角度
	*A B C 三个点 返回的角度是∠ABC的角度
	*/
	__proto.getAngle=function(A,B,C){
		var AB=Math.sqrt(Math.pow(B.x-A.x,2)+Math.pow(B.y-A.y,2));
		var AC=Math.sqrt(Math.pow(B.x-C.x,2)+Math.pow(B.y-C.y,2));
		var BC=Math.sqrt(Math.pow(A.x-C.x,2)+Math.pow(A.y-C.y,2));
		var cosA=(Math.pow(AB,2)+Math.pow(AC,2)-Math.pow(BC,2))/ (2 *AB *AC);
		var angleNum=Math.round(Math.acos(cosA)*180 / Math.PI);
		return angleNum;
	}

