//class com.biz.trans.LoginTrans extends com.klzz.transaction.FilterChainTrans
var LoginTrans=(function(_super){
	function LoginTrans(){
		/**排队状态 */
		this._queueState=-1;
		LoginTrans.__super.call(this);
	}

	__class(LoginTrans,'com.biz.trans.LoginTrans',_super);
	var __proto=LoginTrans.prototype;
	//override start
	__proto.init=function(__param){
		var param=arguments;
		this._queueState=-1;
		SocketHandler.instance.on("message",this,this.onSocketMsg);
		var ld=this.loginData;
		this.req=ObjUtil.mergeObj(this.req,{
			ptl:Protocol.LOGIN[0],
			data:ld,
			hdrKey:Protocol.LOGIN[1]
		},false,true);
		Reporter.reportSLSBase("login_start",{type:"course_init"});
		console.debug("LoginTrans - login parameter:"+JSON.stringify(this.req));
		this.addFilter(new SendMsgFilter());
		this._timeout=5000;
	}

	__proto.execute=function(){
		if (this.resp && this.resp.data){
			var rdata=this.resp.data;
			if (this.resp.cmd==Protocol.LOGIN[1]){
				if(rdata.time > 0){
					VipThink.setServerTime(rdata.time);
				}
				if (rdata.state==0){
					var uvo=rdata.userVO;
					if (!rdata.handled){
						GlobalModel.loginTS=Browser.now();
						this.me.update({
							ip:uvo.ip,
							status:uvo.status,
							currentRoomId:uvo.currentRoomId,
							loginTime:rdata.time
						});
						rdata.handled=true;
					}
					if(uvo && this.me.currentRoomId==uvo.currentRoomId){
						VipThink.userStatus.backupUserList();
					}
					if (this._queueState==-1){
						return false;
						}else if (this._queueState==0){
						}else {
						console.warn("EnterRoomTrans","Queue failed.");
					}
					}else {
					console.warn("LoginTrans","Login failed.");
				}
			}
		}
		return _super.prototype.execute.call(this);
	}

	/**处理socket消息 */
	__proto.onSocketMsg=function(data){
		var ptl=data.cmd;
		var rdata=data.data;
		var state=rdata.state;
		if (ptl==Protocol.GET_QUEUE_DATA[1]){
			this._queueState=state;
			if (this._isSleep)
				this.doFilter(this.req,this.resp);
		}
	}

	/**
	*登录数据
	*/
	__getset(0,__proto,'loginData',function(){
		var uvo=VipThink.user;
		var time=Browser.now();
		if (VipThink.release=="dev"){
			var key="klzz20161010";
			var token=StringUtil.format("key={0}&time={1}&uid={2}",key,time,uvo.id);
			uvo.token=token;
			uvo.cookie={
				klzz_ol_home_uid:uvo.id,
				klzz_ol_home_time:time.toString(),
				klzz_ol_home_token:Sha1.hex(uvo.token)
			};
		};
		var token2=StringUtil.format("app_klzz_key=klzz20161010&app_klzz_time={0}&app_klzz_uId={1}",time,uvo.id);
		return {authData:{
				cookie:uvo.cookie,
				id:uvo.id,
				name:uvo.name,
				userdata:JSON.stringify(uvo.getObject(true)),
				headerimg:uvo.headerImg,
				userType :uvo.userType,
				institution:"test",
				appType:1
			}
		};
	});

	__getset(0,__proto,'completeData',function(){
		var result;
		if (this.status==3)
			result="timeout";
		else if (this.resp)
		result=(this.resp.data)&& this.resp.data.state;
		return {
			result:result,
			user:this.me,
			queueState:this._queueState
		};
	});

	/**当前用户 */
	__getset(0,__proto,'me',function(){
		return VipThink.user;
	});

	LoginTrans.__init$=function(){{
			TransManager.regTransCls("login",LoginTrans);
		};
	}

	return LoginTrans;
})(FilterChainTrans)


