var PlaySoundTrans=(function(_super){
	function PlaySoundTrans(){
		PlaySoundTrans.__super.call(this);
	}

	__class(PlaySoundTrans,'com.biz.trans.PlaySoundTrans',_super);
	var __proto=PlaySoundTrans.prototype;
	__proto.init=function(__param){
		var param=arguments;
		if (!GlobalModel.isInRoom())
			return;
		if (!param[0].data){
			var d=param[0];
			if(VipThink.isAIPlay){
				this.dealBroadcastMessage(d);
				}else {
				if (this.isLockAndNoAuthor){
					if (VipThink.user.userType==1 || VipThink.user.userType==3){
						if (VipThink.user.watchingUser==d.fromId){
							this.dealBroadcastMessage(d);
						}
						if (!VipThink.user.watchingUser && VipThink.user.userType==1){
							this.dealBroadcastMessage(d);
						}
						}else {
						this.dealBroadcastMessage(d);
					}
				}
			}
			}else {
			this.req=param[0];
			this.req.data.fromId=GlobalModel.user.id;
			this.addFilterWithReq(new BroadcastFilter(),this.req);
		}
	}

	__proto.dealBroadcastMessage=function(d){
		if (d.type=="music" || d.type=="lessonMusic"){
			if (d.act=="stopMusic"){
				KlSoundManager.stopMusic(true);
				}else if(d.act=="stopLessonMusic"){
				VipThink.currView && (VipThink.currView).stopMusicUnSync();
				}else {
				if(d.type=="lessonMusic"){
					VipThink.currView && (VipThink.currView).playMusicUnSync(d.url,d.loop,null,d.startTime);
					}else{
					KlSoundManager.playMusic(d.url,d.loop,null,d.startTime,true);
				}
			}
			}else {
			if (d.act=="stopAllSound"){
				KlSoundManager.stopAllSound(true);
				}else {
				KlSoundManager.playSound(d.url,d.loops,null,null,d.startTs,d.type,d.isSkeletonSound,true);
			}
		}
	}

	/**
	*非广播频道的控制者，非收听频道控制着
	*/
	__getset(0,__proto,'isLockAndNoAuthor',function(){
		if (VipThink.isAiAndIsPlaying || VipThink.OPEN_PLAY_BACK){
			return true;
		}
		return !GlobalModel.isLisChannelEditor && !GlobalModel.isBChannelEditor;
	});

	PlaySoundTrans.__init$=function(){{
			TransManager.regTransCls("playSound",PlaySoundTrans);
		}
	}

	return PlaySoundTrans;
})(FilterChainTrans)


