//class com.biz.trans.SendDrawTrans extends com.klzz.transaction.FilterChainTrans
var SendDrawTrans=(function(_super){
	function SendDrawTrans(){
		/**数据列表 */
		this._list=null;
		SendDrawTrans.__super.call(this);
		this._priority=0;
	}

	__class(SendDrawTrans,'com.biz.trans.SendDrawTrans',_super);
	var __proto=SendDrawTrans.prototype;
	// _drawView=VipThink.viewMgr.getDrawView();
	__proto.init=function(__param){
		var param=arguments;
		if (!param || !param[0])
			return;
		if (((param[0])instanceof Array))
			this._list=param[0];
		else
		this._list=[param[0]];
		if (!GlobalModel.isInRoom()){
			var vo=GlobalModel.brushSetVO;
			var props=['isOpenBrush','brushType','thickness','lineColor','isMouseThrough'];
			var propsComp=['visible','brushType','thickness','lineColor','isMouseThrough'];
			for (var i=0,len=this._list.length;i < len;i++){
				var item=this._list[i];
				var idx=props.indexOf(item.propName);
				if (idx !=-1){
					if(item.propName=='isOpenBrush'){
						item.comp[propsComp[idx]]=item.toVal;
					}
					vo[props[idx]]=item.toVal;
				}
				VipThink.nativeAPI.sendToNative("brushSetUpdate",vo.getMyObject());
			}
			return;
		}
		if (((param[0])instanceof Array)){
			this._list=param[0];
		}
		else{
			this._list=[param[0]];
		};
		var gbvo=GlobalModel.brushSetVO;
		var pushData={list:[],handler:null};
		for (var i=0,len=this._list.length;i < len;i++){
			var d=this._list[i];
			var propName=d.propName;
			if (GlobalModel.isLisChannelEditor){
				if (propName=="newDrawNode"){
					var addInfo=SyncAssist.dicDraw.addValue("draw",d.toVal,0,d.toVal[0]);
					SendDrawTrans.currDrawNodeID=addInfo[3];
					pushData.list.push({uId:this.targetChannel,key:"drawNodeList",type:"array",action:{value:SyncAssist.getSyncObj(SendDrawTrans.currDrawNodeID),actType:"add"}});
				}
				else if (propName=="currDrawPoint"){
					pushData.list.push({uId:this.targetChannel,key:SendDrawTrans.currDrawNodeID,type:"array",action:{value:d.toVal,actType:"add"}});
				}
				else if (propName=="drawStatus"){
					pushData.list.push({uId:this.targetChannel,key:"drawStatus",action:{value:this._list[0].toVal}});
				}
				else if (propName=="currWritePoint"){
					pushData.list.push({uId:this.targetChannel,key:SendDrawTrans.currDrawNodeID,type:"string",action:{value:d.toVal,actType:"add"}});
				}
			}
			if (gbvo.myPropNames.indexOf(propName)>-1){
				GlobalModel.globalData={brushSetting:(d.comp).setVO.getMyObject()};
			}
		}
		if (pushData.list.length > 0){
			pushData.notify=GlobalModel.willNotify;
			this.addFilterWithReq(new UpdateUserCacheFilter(),pushData);
		}
	}

	/**要更改的频道ID */
	__getset(0,__proto,'targetChannel',function(){
		return GlobalModel.listenChannel.id;
	});

	SendDrawTrans.currDrawNodeID=null;
	SendDrawTrans.__init$=function(){{
			TransManager.regTransCls("sendDraw",SendDrawTrans);
		};
	}

	return SendDrawTrans;
})(FilterChainTrans)


