//class com.biz.trans.SetBChannelTrans extends com.klzz.transaction.FilterChainTrans
var SetBChannelTrans=(function(_super){
	function SetBChannelTrans(){
		// private var _chlVO:ChannelVO;
		this._needToUpdate=false;
		SetBChannelTrans.__super.call(this);
		this._priority=0;
	}

	__class(SetBChannelTrans,'com.biz.trans.SetBChannelTrans',_super);
	var __proto=SetBChannelTrans.prototype;
	/**param:[频道ID， 控制者ID] */
	__proto.init=function(__param){
		var param=arguments;
		if (!GlobalModel.isRoomOwner || !GlobalModel.isInRoom())
			return;
		var _chlVO=param[0];
		this._needToUpdate=false;
		if (!_chlVO.isValid)
			return;
		var gd=GlobalModel.globalData;
		if (!_chlVO.id && !_chlVO.editorID){
			if (GlobalModel.currBChannel.id){
				this._needToUpdate=true;
				gd.bChannelEditor=_chlVO.editorID;
				gd.bChannel=_chlVO.id;
				}else {
				console.warn("SetBChannelTrans","无法解锁喔！怎么回事？");
			}
			}else if (_chlVO.id && _chlVO.editorID==-1){
			gd.bChannel=_chlVO.id;
			this._needToUpdate=true;
			}else if (_chlVO.editorID && _chlVO.id==-1 && gd.bChannelEditor !=_chlVO.editorID){
			gd.bChannelEditor=_chlVO.editorID;
			this.addFilterWithReq(new ChangeOpIDFilter(),{
				authorUserId:gd.bChannelEditor,
				targetUId:gd.bChannel
			});
			}else if (_chlVO.editorID && _chlVO.id > 0){
			if (gd.bChannel && gd.bChannel !=_chlVO.id){
				this.addFilterWithReq(new ChangeOpIDFilter(),{
					authorUserId:gd.bChannel,
					targetUId:gd.bChannel
				});
			}
			if (_chlVO.compareWith(gd,{"id":"bChannel","editorID":"bChannelEditor"})){
				gd.bChannelEditor=_chlVO.editorID;
				gd.bChannel=_chlVO.id;
				this.addFilterWithReq(new ChangeOpIDFilter(),{
					authorUserId:gd.bChannelEditor,
					targetUId:gd.bChannel
				});
				delete gd.otherSetting.watchMap[GlobalModel.user.id];
			}
		}
		if(SwitchQuestionCtr.isQuestionPage()){
			if(!_chlVO.id && !_chlVO.editorID){
				gd.otherSetting.autoOpenCutOffBoo=true;
			}
			else if(_chlVO.id==_chlVO.editorID==GlobalModel.roomOwner){
				gd.otherSetting.autoOpenCutOffBoo=false;
			}
		}
		else if(SwitchQuestionCtr.isQuestionLastPage()){
			gd.otherSetting.autoOpenCutOffBoo=false;
		}
		this.addFilterWithReq(new SaveDataFilter(),{
			value:gd,
			key:"global"
		});
	}

	// }
	__proto.addFilterWithReq=function(filter,reqData){
		this._needToUpdate=true;
		_super.prototype.addFilterWithReq.call(this,filter,reqData);
	}

	SetBChannelTrans.__init$=function(){{
			TransManager.regTransCls("setBChannel",SetBChannelTrans);
		};
	}

	return SetBChannelTrans;
})(FilterChainTrans)


