	__proto.getChangeData=function(curStr,lastStr,selectionEnd){
		var max=Math.max(curStr.length,lastStr.length);
		var curLen=curStr.length;
		var lastLen=lastStr.length;
		var leftCount=max-(curLen-selectionEnd);
		var rightCount=max-leftCount;
		var leftIndex=selectionEnd;
		var leftCurStr=curStr.substr(0,curLen-rightCount);
		var leftLastStr=lastStr.substr(0,lastLen-rightCount);
		for (var i=0;i <=leftCount;i++){
			if (leftCurStr[i] !=leftLastStr[i]){
				leftIndex=i;
				break ;
			}
		};
		var rightCurStr=curStr.substr(curLen-rightCount);
		var rightLastStr=lastStr.substr(lastLen-rightCount);
		var rightCurLen=rightCurStr.length;
		var rightLastLen=rightLastStr.length;
		rightCount=Math.max(rightCurLen,rightLastLen);
		var rightIndex=max-rightCount;
		for (var j=0;j < rightCount;j++){
			if (rightCurStr[rightCurLen-j-1] !=rightLastStr[rightLastLen-j-1]){
				rightIndex=max-j;
				break ;
			}
		};
		var str=leftCurStr.substr(leftIndex);
		var startIndex=leftIndex;
		var endIndex=rightIndex;
		if (curLen > lastLen){
			endIndex=str.length-(curLen-lastLen)+startIndex;
		}
		return {str:str,startIndex:startIndex,endIndex:endIndex};
	}

