	// console.debug("wuyu=====test","barRangeX:",barRangeX,"barRangeY:",barRangeY,"alearyBarX:",alearyBarX,"alearyBarY:",alearyBarY,"horiBarXRate:",horiBarXRate,"vertBarYRate:",vertBarYRate);
