	__proto.setEditShow=function(type){
		this.setMaskBgVisible(false);
		if (WhiteBoardNewConst.isLiveStatus()){
			if (type==1){
				this.teacheEditBg.visible=true;
				this.penFontSelectBox.visible=true;
				this.othertSelectBox.visible=true;
				this.stuEditBg.visible=false;
				this.shouhuiBtn.visible=false;
				this.xiafaBtn.visible=false;
				this.editGray.visible=false;
			}
			else if (type==2){
				this.teacheEditBg.visible=false;
				this.stuEditBg.visible=false;
				this.stuShouhuiBtn.visible=false;
			}
			else if (type==3){
				this.teacheEditBg.visible=true;
				this.penFontSelectBox.visible=true;
				this.othertSelectBox.visible=true;
				this.stuEditBg.visible=false;
				this.shouhuiBtn.visible=false;
				this.xiafaBtn.visible=true;
				this.editGray.visible=false;
				this.teDefealtSelectOperate();
			}
			else if (type==4){
				this.teacheEditBg.visible=true;
				this.stuEditBg.visible=false;
				this.shouhuiBtn.visible=true;
				this.xiafaBtn.visible=false;
				this.penFontSelectBox.visible=false;
				this.othertSelectBox.visible=false;
				this.editGray.visible=true;
			}
			else if (type==5){
				this.teacheEditBg.visible=false;
				this.stuEditBg.visible=true;
				this.stuShouhuiBtn.visible=true;
				this.stuOperateSelectClick("stuPenBtn");
			}
			else if (type==6){
				this.teacheEditBg.visible=true;
				this.penFontSelectBox.visible=true;
				this.othertSelectBox.visible=true;
				this.stuEditBg.visible=false;
				this.shouhuiBtn.visible=false;
				this.xiafaBtn.visible=false;
				this.teDefealtSelectOperate();
				this.editGray.visible=false;
			}
			else if (type==8){
				this.teacheEditBg.visible=false;
				this.stuEditBg.visible=false;
				this.stuShouhuiBtn.visible=true;
				this.stuShouhuiBtn.visible=false;
			}
			else if (type==7){
				this.teacheEditBg.visible=true;
				this.penFontSelectBox.visible=true;
				this.othertSelectBox.visible=true;
				this.stuEditBg.visible=false;
				this.shouhuiBtn.visible=false;
				this.xiafaBtn.visible=false;
				this.editGray.visible=false;
			}
		}
		else{
			this.teacheEditBg.visible=false;
			this.stuEditBg.visible=false;
			this.shouhuiBtn.visible=false;
			this.xiafaBtn.visible=false;
			this.stuShouhuiBtn.visible=false;
		}
	}

	__proto.teDefealtSelectOperate=function(){
		this.refreshTeEditSelectStatus("penBtn");
		this.sendTeOpreatetSelectCallBack('white_board_pen_select');
		this.refreshPenColorTipFlag();
	}

	__proto.showXuanFuTip=function(target,isShow){
		if (isShow){
			var str="";
			var str2="";
			if (target.name=="penBtn" || target.name=="stuPenBtn"){
				str="画笔";
			}
			else if (target.name=="fontBtn"){
				str="双击白板新增";
				str2="文本框";
			}
			else if (target.name=="eraseBtn" || target.name=="stuEraseBtn"){
				str="橡皮擦";
			}
			else if (target.name=="clearBtn"){
				str="清除";
			}
			this.showText.text=str;
			this.showText2.text=str2;
			this.showText2.x=str2=="" ? 0 :132;
			this.shouqiTip.width=str.length *this.showText.fontSize+str2.length *this.showText2.fontSize+16;
			var parent=target.parent;
			var globalPos=parent.localToGlobal(new Point(target.x,target.y),true);
			var point1=target.toParentPoint(new Point(target.x,target.y));
			var localPos=this.boardBox.globalToLocal(globalPos,true);
			this.shouqiTip.x=localPos.x+25;
			this.shouqiTip.y=localPos.y-41;
		}
		this.shouqiTip.visible=isShow;
	}

