	__proto.teOperateSelectClick=function(name){
		console.log("name:"+name);
		this.refreshTeEditSelectStatus(name);
		var selectType="";
		this.penSelectBox.visible=false;
		this.clearSelectBox.visible=false;
		if (name=="penBtn"){
			this.setMaskBgVisible(true);
			this.penSelectBox.visible=true;
			this.lineBox.visible=true;
			this.fonSizeBox.visible=false;
			var point1=new Point(this.penBtn.x,this.penBtn.y);
			var globalPos=this.penFontSelectBox.localToGlobal(point1,true);
			var localPos=this.teacheEditBg.globalToLocal(globalPos,true);
			this.penSelectBox.x=localPos.x-40;
			this.penSelectBox.y=localPos.y+60;
			selectType='white_board_pen_select';
			this.refreshPenColorTipFlag();
			this.sendDaDian(this.getPointClickName(),"小白板-画笔");
		}
		else if (name=="clearBtn"){
			this.clearSelectBox.visible=true;
		}
		else if (name=="eraseBtn"){
			selectType='white_board_erase';
			this.sendDaDian(this.getPointClickName(),"小白板-橡皮擦");
		}
		else if (name=="fontBtn"){
			this.setMaskBgVisible(false);
			this.penSelectBox.visible=false;
			this.lineBox.visible=false;
			this.fonSizeBox.visible=true;
			var point1=new Point(this.fontBtn.x,this.fontBtn.y);
			var globalPos=this.penFontSelectBox.localToGlobal(point1,true);
			var localPos=this.teacheEditBg.globalToLocal(globalPos,true);
			this.penSelectBox.x=localPos.x-40;
			this.penSelectBox.y=localPos.y+60;
			selectType='white_board_font_select';
			this.sendDaDian(this.getPointClickName(),"小白板-文本框");
		}
		else if (name=="returnBtn"){
			selectType='white_board_return';
		}
		if (name !="clearBtn"){
			this.sendTeOpreatetSelectCallBack(selectType);
		}
	}

	__proto.stuOperateSelectClick=function(name){
		this.refreshStuEditSelectStatus(name);
		var selectType="";
		var operateIndex=0;
		if (name=="stuPenBtn"){
			selectType='white_board_pen_select';
			this.sendDaDian("student_zbj_click","小白板-画笔");
			operateIndex=0;
		}
		else if (name=="stuEraseBtn"){
			this.sendDaDian("student_zbj_click","小白板-橡皮擦");
			selectType='white_board_erase';
		}
		else if (name=="stuShouhuiBtn"){
			selectType='white_board_stu_shouhui';
			this.sendDaDian("student_zbj_click","小白板-关闭");
			this.sendStuCloseInfo();
		}
		this.sendStuOpreatetSelectCallBack(selectType);
	}

	__proto.btnSelectClick=function(name){
		if (name=="lastBtn"){
			this.curPage--;
			if (this.curPage < 1){
				this.curPage=1;
			}
			else{
				this.sendDaDian(this.getPointClickName(),"小白板-上一页");
				this.sendPageChangeInfo();
			}
		}
		else if (name=="nextBtn"){
			this.curPage++;
			if (this.curPage > WhiteBoardNewConst.TOTAL_PAGE_NUMBER){
				this.curPage=WhiteBoardNewConst.TOTAL_PAGE_NUMBER;
			}
			else{
				this.sendDaDian(this.getPointClickName(),"小白板-下一页");
				this.sendPageChangeInfo();
			}
		}
		else if (name=="xiafaBtn"){
			this.sendXiaFaInfo();
			this.sendDaDian(this.getPointClickName(),"小白板-全部下发");
		}
		else if (name=="submitBtn"){
			this.sendStuSubmitInfo();
			this.sendDaDian("student_zbj_click","小白板-提交");
		}
		else if (name=="shouhuiBtn"){
			this.sendShouHuiInfo();
			this.sendDaDian(this.getPointClickName(),"小白板-全部收回");
		}
	}

	__proto.refreshPageBtnStatus=function(){
		if (this.totalPage <=1){
			this.setLastBtnStatus(false);
			this.setNextBtnStatus(true);
		}
		else if (this.curPage==1){
			this.setLastBtnStatus(false);
			this.setNextBtnStatus(true);
		}
		else if (this.curPage >=WhiteBoardNewConst.TOTAL_PAGE_NUMBER){
			this.setLastBtnStatus(true);
			this.setNextBtnStatus(false);
		}
		else{
			this.setLastBtnStatus(true);
			this.setNextBtnStatus(true);
		}
	}

	__proto.setLastBtnStatus=function(isCanClickTemp){
		var normal=this.lastBtn.getChildByName("normal");
		var disenable=this.lastBtn.getChildByName("disenable");
		if (isCanClickTemp){
			normal.visible=true;
			disenable.visible=false;
		}
		else{
			normal.visible=false;
			disenable.visible=true;
		}
	}

	__proto.setNextBtnStatus=function(isCanClickTemp){
		var normal=this.nextBtn.getChildByName("normal");
		var disenable=this.nextBtn.getChildByName("disenable");
		if (isCanClickTemp){
			normal.visible=true;
			disenable.visible=false;
		}
		else{
			normal.visible=false;
			disenable.visible=true;
		}
	}

	__proto.eraseSelectClick=function(name){
		this.clearSelectBox.visible=false;
		if (name=="clearSelectOkBtn"){
			this.sendDeleteAllInfo();
			this.sendDaDian(this.getPointClickName(),"小白板-全部清除");
			this.sendTeOpreatetSelectCallBack('white_board_clear');
		}
	}

	__proto.refreshTeEditSelectStatus=function(selectColorName){
		var len=this.penFontSelectBox.numChildren;
		for (var index=0;index < len;index++){
			var element=this.penFontSelectBox.getChildAt(index);
			var select=element.getChildByName("select");
			var normal=element.getChildByName("normal");
			if (element.name==selectColorName){
				select.visible=true;
				normal.visible=false;
			}
			else{
				select.visible=false;
				normal.visible=true;
			}
		}
		len=this.othertSelectBox.numChildren;
		for (var index1=0;index1 < len;index1++){
			var element1=this.othertSelectBox.getChildAt(index1);
			var select1=element1.getChildByName("select");
			if (select1 !=null){
				var normal1=element1.getChildByName("normal");
				if (element1.name==selectColorName){
					select1.visible=true;
					normal1.visible=false;
				}
				else{
					select1.visible=false;
					normal1.visible=true;
				}
			}
		}
	}

	__proto.refreshStuEditSelectStatus=function(selectColorName){
		var len=this.stuPenFontSelectBox.numChildren;
		for (var index=0;index < len;index++){
			var element=this.stuPenFontSelectBox.getChildAt(index);
			var select=element.getChildByName("select");
			var normal=element.getChildByName("normal");
			if (element.name==selectColorName){
				select.visible=true;
				normal.visible=false;
			}
			else{
				select.visible=false;
				normal.visible=true;
			}
		}
	}

	__proto.refreshPenColorTipFlag=function(){
		this.penColorTipFlag.skin="share/ui/WhiteBoardNew/select_dot_tip_"+this.penColorIndex+".png";
	}

	__proto.shouQiMouseHandler=function(e){
		var name=e.target.name;
		this.showXuanFuTip(e.target,false);
		this.refreshTeacheEditSelectTip(null);
		this.refreshStuEditSelectTip(null);
		this.refreshLineSelectTip(null,false);
		switch (e.type){
			case "mouseover":
				if (name=="penBtn" || name=="fontBtn" || name=="eraseBtn" || name=="returnBtn" || name=="clearBtn"){
					this.refreshTeacheEditSelectTip(e.target);
					this.showXuanFuTip(e.target,true);
				}
				if (name=="stuPenBtn" || name=="stuEraseBtn"){
					this.refreshStuEditSelectTip(e.target);
					this.showXuanFuTip(e.target,true);
				}
				else if (e.target.name.includes("color_")){
					this.refreshColorSelectTip(e.target,true);
				}
				else if (e.target.name.includes("line_")){
					this.refreshLineSelectTip(e.target,true);
				}
				else if (e.target.name.includes("font_")){
					this.refreshFonteSelectTip(e.target,true);
				}
				break ;
			case "mouseout":
				if (e.target.name.includes("color_")){
					this.refreshColorSelectTip(null,false);
				}
				if (e.target.name.includes("line_")){
					this.refreshLineSelectTip(null,false);
				}
				if (e.target.name.includes("font_")){
					this.refreshFonteSelectTip(null,false);
				}
				break ;
			}
	}

