	/**
	*获取指定组件的datasource
	*@param comp 目标组件
	*@param caller:*=null 调用者
	*@return 组件的datasource
	*/
	__proto.getCompDataSource=function(comp,caller){
		if (!caller && (!comp || !comp.name || !comp.dataSource))
			return null;
		var ds;
		if (!caller){
			ds={name:comp.name,dataSource:comp.dataSource};
		}
		if (comp.numChildren > 0){
			var childs=[];
			for (var i=0,len=comp.numChildren;i < len;i++){
				var ch=comp.getChildAt(i);
				if ((ch instanceof laya.ui.Component )){
					var cd=this.getCompDataSource(ch);
					cd && (childs[childs.length]=cd);
				}
			}
			if (caller)
				ds=childs;
			else if (childs.length > 0)
			ds.childs=childs;
		}
		return ds;
	}

	/**
	*设置子组件的datasource
	*@param parent 父节点
	*@param dsObj 组件数据源{name,datasource,childs}
	*/
	__proto.setChildDataSource=function(parent,dsObj){
		if (!parent || !dsObj)
			return false;
		var child=parent.getChildByName(dsObj.name);
		if (!child)
			return false;
		child.dataSource=dsObj.dataSource;
		if (dsObj.childs && dsObj.childs.length > 0){
			for (var i=0,len=dsObj.childs.length;i < len;i++){
				this.setChildDataSource(child,dsObj.childs[i]);
			}
		}
		return true;
	}

