					x_=d==3 ? this._currIpt.x+this._currIpt.width / 2 *this._currIpt.scaleX :(d==4 ? this._currIpt.x-this._currIpt.width / 2 *this._currIpt.scaleX :this._currIpt.x);
					y_=d==1 ? this._currIpt.y :(d==2 ? this._currIpt.y-this._currIpt.height *this._currIpt.scaleY :this._currIpt.y-this._currIpt.height / 2 *this._currIpt.scaleY);
					x_+=offset[0]-selfOffset[0]+currIptPivotOffset[0];
