	/*
	获取错误输入的输入框索引
	*/
	__proto.getWrongIdx=function(){
		if(!this.answer)
			return null;
		var str;
		if((typeof this.answer=='number')){
			str=String(this.answer)
			}else{
			str=this.answer;
		};
		var wrongIdx=[];
		var answerArr;
		var kipi;
		switch(this.mode){
			case 1:{
					answerArr=str.split(",");
					for (var i=0;i < answerArr.length;i++){
						kipi=this.getChildAt(i);
						if(!this.singleAnswerCheck(kipi,answerArr[i]))
							wrongIdx.push(i);
					}
					break ;
				}
			case 3:{
					var answerGroup=this.answer.split("|");
					for (var i=0;i < answerGroup.length;i++){
						var kipBox=this.getChildAt(i);
						answerArr=answerGroup[i].split(",");
						for (var j=0;j < answerArr.length;j++){
							kipi=kipBox.getChildAt(j);
							if(!this.singleAnswerCheck(kipi,answerArr[j]))
								wrongIdx.push([i,j]);
						}
					}
					break ;
				}
			}
		return wrongIdx;
	}

