//class com.biz.ui.VideoView extends com.klzz.ui.KlView
var VideoView=(function(_super){
	function VideoView(cfg,name){
		/**上一个同步状态 */
		this._lastAct="";
		/**更新时刻帧数 <b>关键状态变化需要时间间隔超过同步数据采样间隔</b>*/
		this._currFrame=0;
		this._data={};
		this._version=null;
		this._isDev=true;
		this._prepared=false;
		this._reference=null;
		// 是否全屏
		this._fill=0;
		// 是否自动播放
		this._autoPlay=0;
		// 播放完是否自动隐藏
		this._hide=0;
		this._hasPrepared=false;
		VideoView.__super.call(this,cfg,name);
		this.isVideoView=true;
	}

	__class(VideoView,'com.biz.ui.VideoView',_super);
	var __proto=VideoView.prototype;
	//console.debug("videoView test:","VideoView");
	__proto.createChildren=function(){
		_super.prototype.createChildren.call(this);
		var img=new Image("share/bg_1.jpg");
		img.size(1920,1080);
		this.addChild(img);
	}

	//console.debug("videoView test:","createChildren");
	__proto.initView=function(byReset){
		(byReset===void 0)&& (byReset=false);
		ViewManager.instance.on("mainViewPrepared",this,this.onPrepared);
		this._currFrame=Laya.timer.currFrame;
		if (byReset){
			VipThink.nativeAPI.noticeNative({args:{type:"video",data:{act:"stop",time:0,isEnd:false}}});
		}
	}

	__proto.checkAutoPlay=function(){
		if(!VipThink.user.isTech && !VipThink.isAI){
			this.autoPlay=0;
			return false;
		}
		if(this.config.param && this.config.param.isAutoPlay===1){
			this.autoPlay=1;
			return true;
		}
		this.autoPlay=0;
		return false;
	}

	__proto.onPrepared=function(data){
		if (this._hasPrepared)
			return;
		this._hasPrepared=true;
		if (VipThink.viewMgr.currPage.currView.name !=this.name){
			return;
		}
		if(VipThink.viewMgr.getMediaView()&& VipThink.viewMgr.getMediaView().currTabIsLayaCourse()==false){
			return;
		}
		this.handlerVideoUrl();
	}

	__proto.getShareVideoUrl=function(){
		if(this.config.param && this.config.param.vName){
			var urlPre="share/animation/autoVideo/v5/";
			return urlPre+this.config.param.vName+".mp4";
		}
		return null;
	}

	__proto.getVideoUrl=function(){
		var videoUrl=this.getShareVideoUrl();
		if(videoUrl){
			return videoUrl;
		}
		return VipThink.viewMgr.currPage.currView.config.videoUrl;
	}

	/**
	*@Author:Snow
	*@description:处理视频URL
	*@param {*}
	*@return {*}
	*/
	__proto.handlerVideoUrl=function(){
		this.checkAutoPlay();
		var videoUrl=this.getVideoUrl();
		var techVideoUrl=VipThink.viewMgr.currPage.currView.config.techVideoUrl;
		if (!videoUrl){
			alert("视频关卡未配置videoUrl参数");
			return;
		}
		this.dealVideoUrl(videoUrl);
		if (!techVideoUrl){
			console.log("未配置techVideoUrl参数，无需播放老师视频")
			return;
		}
		this.dealVideoUrl(techVideoUrl,"techVideo");
	}

	__proto.dealVideoUrl=function(videoUrl,type){
		(type===void 0)&& (type="video");
		console.debug("VideoView videoUrl:"+videoUrl);
		this._prepared=false;
		if (videoUrl.indexOf("http://")!=-1 || videoUrl.indexOf("https://")!=-1){
			this.sendUrl(videoUrl,type);
		}
		else{
			var courseUrl=VipThink.config.courseCfg ? VipThink.config.courseCfg.url :null;
			var url
			if (videoUrl.indexOf("share/animation/")!=-1){
				url=videoUrl;
			}
			else{
				url=courseUrl ? (courseUrl+'/'+videoUrl):videoUrl;
			};
			var versionUrl;
			var fullUrl=URL.formatURL(url);
			if (fullUrl.indexOf("/lessons/")==-1 && fullUrl.indexOf("share/animation")==-1){
				this._isDev=true;
				this.sendUrl(url,type);
			}
			else{
				var idx=0;
				if (fullUrl.indexOf("share/animation")!=-1){
					idx=fullUrl.indexOf("/share/animation");
				}
				else{
					idx=fullUrl.indexOf("/lessons/");
				}
				this._isDev=false;
				var customUrl=URL.customFormat(url);
				if (customUrl){
					this.sendUrl(customUrl,type);
				}
				else{
					console.error('videoView customUrl is undefined');
				}
			}
		}
	}

	/**
	*发送视频url给native
	*/
	__proto.sendUrl=function(url,type){
		(type===void 0)&& (type="video");
		if (!url && type=="video"){
			alert("视频url地址为空");
			console.error("视频关卡：视频url地址为空");
			return;
		};
		var videoElement=null;
		if (VipThink.release=="dev" && (type=='video' || type=='techVideo')&& !VipThink.isAI){
			if (type=='video')
				this.clearVideo();
			var sc=0.7;
			var w=1920 *sc;
			var h=1080 *sc;
			var l=(1920-w)/ 2;
			var r=(1080-h)/ 2;
			var sPos=[0,0];
			if (type=="techVideo"){
				sc=0.2;
				w=1920 *sc;
				h=1080 *sc;
				l=(1920-w)/ 2;
				r=(1080-h)/ 2;
				sPos=[700,-400];
			}
			this._reference=new Sprite();
			this._reference.x=sPos[0];
			this._reference.y=sPos[1];
			videoElement=Browser.createElement("video");
			Browser.document.body.appendChild(videoElement);
			videoElement.style.zInddex=Render.canvas.style.zIndex+1;
			videoElement.style.position='absolute';
			videoElement.src=url;
			videoElement.controls=true;
			this.addChild(this._reference);
			this._reference.size(w,h);
			this._reference.rotation=90;
			Utils.fitDOMElementInArea.apply(this,[videoElement,this._reference,l,r,this._reference.width,this._reference.height]);
			Laya.stage.on("resize",this,Utils.fitDOMElementInArea,[videoElement,this._reference,l,r,this._reference.width,this._reference.height]);
		};
		var obj={act:"videoUrl",url:url
		};
		var mode;
		var duration=0;
		if(this.config && this.config.configObj){
			if(this.config.configObj.mode){
				mode=this.config.configObj.mode;
			}
			if(this.config.configObj.duration){
				duration=this.config.configObj.duration;
			}
		}
		if(mode !=""){
			obj.mode=mode;
		}
		if(duration > 0){
			obj.duration=duration;
		}
		if (type !="nomal"){
			obj.fill=this._fill,obj.autoPlay=this._autoPlay,obj.hide=this._hide
			if ((type=="video" && !VipThink.viewMgr.currPage.currView.config.techVideoUrl && VipThink.config.courseType==82)|| VipThink.config.courseType==81){
				obj.fill=1;
			}
			if (VipThink.config.courseType==82 || VipThink.config.courseType==81){
				obj.autoPlay=1;
				obj.hide=1;
			}
			if(this.autoPlay){
				this.noticeNativeToStartPlayVideo(videoElement);
			}
		};
		var msg={args:{type:type,data:obj}}
		VipThink.nativeAPI.noticeNative(msg);
		VipThink.debugLog("VideoView","SendUrl to Native！url:%s",JSON.stringify(msg));
		this._lastAct="";
		this._currFrame=Laya.timer.currFrame;
		this._prepared=true;
	}

	__proto.clearView=function(){
		console.log("-----------------VideoView clearView----------------"+this.name);
		if (! (VipThink.viewMgr.currPage.currView instanceof com.biz.ui.VideoView )){
			this.fill=this.autoPlay=this.hide=0;
			this.sendUrl('','nomal');
		}
		ViewManager.instance.off("mainViewPrepared",this,this.onPrepared);
		this._hasPrepared=false;
		this.clearVideo();
		_super.prototype.clearView.call(this);
	}

	__proto.clearVideo=function(){
		var dbody=Browser.document.body;
		if(dbody && dbody.children){
			var len=dbody.children.length;
			for (var i=0;i <len;i++){
				var node=dbody.children[i];
				if(node.localName=="video"){
					dbody.removeChild(node);
					i--;
					len--;
				}
			}
		}
		Laya.stage.off("resize",this,Utils.fitDOMElementInArea);
		this.graphics.clear();
		if (this._reference){
			this.removeChild(this._reference);
			this._reference=null;
		}
	}

	//}
	__proto.noticeNativeToStartPlayVideo=function(videoEle){
		var data={act:"start",time:0,isEnd:false};
		Laya.timer.frameOnce(5,this,function(){
			if(videoEle){
				videoEle.play();
				}else{
				VipThink.nativeAPI.noticeNative({args:{type:"video",data:data}});
			}
		});
	}

	__proto.command=function(param){
		console.log("VideoView command param:%s",JSON.stringify(param));
		var act=param.args.act;
		var ct=param.args.time ? param.args.time :0;
		var _isEnd=param.args.isEnd ? true :false;
		if (act=="stop" && _isEnd){
			if (VipThink.cfgCourse.isNoticeVideoEnd){
				KlEventCenter.event("videoEnd");
			}
			else if (VipThink.viewMgr.currPage.currView.config.jumpNextLevel){
				VipThink.nativeAPI.nextPage();
			}
			return;
		}
		this.data={time:ct,isEnd:_isEnd,act:act};
	}

	/**派发录制数据 */
	__proto.eventPlaybackrecordData=function(data){
		if (VipThink.OPEN_PLAY_BACK_RECORD && VipThink.config.courseType !=8){
			KlEventCenter.event("recordData",[{action:'v',data:data}]);
		}
	}

	__proto.doAwake=function(){
		_super.prototype.doAwake.call(this);
		this.handlerVideoUrl();
	}

	__proto.doSleep=function(){
		_super.prototype.doSleep.call(this);
		this.sendUrl('','nomal');
		this.clearVideo();
	}

	/**
	*强行刷新
	*/
	__proto.reflash=function(){
		this._currFrame=Laya.timer.currFrame;
		this.handlerVideoUrl();
	}

	__getset(0,__proto,'hide',function(){
		return this._hide;
		},function(value){
		this._hide=value;
	});

	__getset(0,__proto,'data',function(){
		return this._data;
		},function(value){
		var _act=value.act;
		if (this._lastAct=="start" && _act=="play"){
			if ((Laya.timer.currFrame-this._currFrame)<=1){
				return;
			}
		}
		if (this._lastAct=="end" && _act=="stop"){
			return;
		}
		this.eventPlaybackrecordData(ObjUtil.deepClone(value));
		console.debug("Video sync data:",JSON.stringify(value)," currFrame:"+this._currFrame," lastAct:"+this._lastAct);
		this.sync("data",this._data,value);
		this._data=value;
		if (this._lastAct !=_act){
			if ("play" !=_act || ("play"==_act && ""==this._lastAct)){
				console.debug("Video noticeNative ACT:",_act);
				VipThink.nativeAPI.noticeNative({args:{type:"video",data:{act:_act,time:value.time,isEnd:value.isEnd}}});
			}
		}
		this._lastAct=_act;
		this._currFrame=Laya.timer.currFrame;
	});

	__getset(0,__proto,'autoPlay',function(){
		return this._autoPlay;
		},function(value){
		this._autoPlay=value;
	});

	__getset(0,__proto,'fill',function(){
		return this._fill
		},function(value){
		this._fill=value;
	});

	VideoView.VIDEO_ACT_START="start";
	VideoView.VIDEO_ACT_PLAY="play";
	VideoView.VIDEO_ACT_STOP="stop";
	VideoView.VIDEO_ACT_END="end";
	return VideoView;
})(KlView)


