		/**第几段对话的id*/
		this._idxCurrAni=0;
		/**动画容器*/
		this._boxAni=null;
		/**已播放音效列表 */
		this._soundList=[];
		/**控制播放按钮 */
		this._btnControl=null;
		/**是否播放中 */
		this._isPlaying=false;
		/**是否已经加载动画完成*/
		this._hasCreatPlayer=false;
		this.bg=null;
		this._mReset=false;
